import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { operatorSetting } from "./client.js";
import { buildMcpEnvironment } from "./mcp.js";
import { extractCompilerDiagnostics, Diagnostic } from "./diagnostics.js";

export interface TestRunResult {
  command: string;
  success: boolean;
  /** The verifier hit its deadline (runner `timed_out`, or the bridge got no answer). Never combined with success. */
  timedOut?: boolean;
  /** The verifier process's exit code, when the runner reported one. */
  exitCode?: number;
  /** The executor itself failed (it returned failure, threw, or gave no exit status): the command may never have run. */
  executorFailed?: boolean;
  rawOutput: string;
  failures: string[];
  diagnostics: Diagnostic[];
}

export type TestCommandExecutor = (command: string) => Promise<{ success: boolean; output: string; error?: string; timedOut?: boolean }>;

export const DEFAULT_VERIFIER_TIMEOUT_SECS = 300;

export function verifierTimeoutSecs(configured?: number): number {
  if (typeof configured === "number" && Number.isFinite(configured) && configured > 0) {
    return Math.floor(configured);
  }
  const envVal = Number(process.env.NEXUS_VERIFIER_TIMEOUT_SECS);
  if (Number.isFinite(envVal) && envVal > 0) {
    return Math.floor(envVal);
  }
  return DEFAULT_VERIFIER_TIMEOUT_SECS;
}

function validateFilterPattern(filterPattern?: string): string | undefined {
  if (!filterPattern) return undefined;
  // The filter is interpolated into a shell command: letters, digits and `_ : . / -` with single spaces only (no
  // newline, quote or shell metacharacter), and it may not start with `-` (it would become a runner flag).
  const trimmed = filterPattern.trim();
  if (!trimmed) return undefined;
  if (!/^[A-Za-z0-9_:./ -]+$/.test(trimmed) || trimmed.startsWith("-")) {
    throw new Error(`Invalid test filter pattern '${filterPattern}': contains unsafe characters.`);
  }
  return trimmed;
}

/**
 * Python tests with no project configuration (no pyproject.toml / setup.py): `test_*.py` files in `tests/` or at the
 * root, run with the standard library's unittest (always present, unlike pytest).
 */
function unittestLayout(root: string): DiscoveredVerifier | null {
  const testFiles = (dir: string) => {
    try {
      return fs.readdirSync(path.join(root, dir)).filter((name) => /^test_.*\.py$/.test(name));
    } catch {
      return [];
    }
  };
  if (testFiles("tests").length) return { command: "python3 -m unittest discover -s tests", evidence: `tests/${testFiles("tests")[0]}` };
  if (testFiles("test").length) return { command: "python3 -m unittest discover -s test", evidence: `test/${testFiles("test")[0]}` };
  if (testFiles(".").length) return { command: "python3 -m unittest discover", evidence: testFiles(".")[0] };
  return null;
}

export interface DiscoveredVerifier {
  command: string;
  /** Repository file that justifies selecting this verifier. */
  evidence: string;
}

/**
 * Select a verifier only when repository files justify one. There is no `npm test` fallback:
 * a workspace with no applicable verifier has none (returns null).
 */
export function discoverVerifier(workspace: string, filterPattern?: string): DiscoveredVerifier | null {
  const root = path.resolve(workspace);
  const filter = validateFilterPattern(filterPattern);
  const has = (p: string) => fs.existsSync(path.join(root, p));

  if (has("Makefile")) {
    try {
      if (/^test:/m.test(fs.readFileSync(path.join(root, "Makefile"), "utf-8"))) {
        return {
          command: filter ? `make test FILTER="${filter}"` : "make test",
          evidence: "Makefile:test",
        };
      }
    } catch {}
  }
  if (has("Cargo.toml")) {
    return {
      command: filter ? `cargo test -- ${filter}` : "cargo test",
      evidence: "Cargo.toml",
    };
  }
  if (has("core/Cargo.toml")) {
    return {
      command: filter
        ? `cargo test --manifest-path core/Cargo.toml -- ${filter}`
        : "cargo test --manifest-path core/Cargo.toml",
      evidence: "core/Cargo.toml",
    };
  }

  const npmTest = (pkgRel: string): boolean => {
    try {
      const pkg = JSON.parse(fs.readFileSync(path.join(root, pkgRel), "utf-8"));
      const script = pkg?.scripts?.test;
      return typeof script === "string" && script.trim().length > 0 && !/no test specified/i.test(script);
    } catch {
      return false;
    }
  };
  if (has("package.json") && npmTest("package.json")) {
    return {
      command: filter ? `npm test -- -t "${filter}"` : "npm test",
      evidence: "package.json:scripts.test",
    };
  }
  if (has("cli/package.json") && npmTest("cli/package.json")) {
    return {
      command: filter ? `npm --prefix cli test -- -t "${filter}"` : "npm --prefix cli test",
      evidence: "cli/package.json:scripts.test",
    };
  }

  if (has("pyproject.toml") || has("setup.py")) {
    return {
      command: filter ? `pytest -k "${filter}"` : "pytest",
      evidence: has("pyproject.toml") ? "pyproject.toml" : "setup.py",
    };
  }
  if (has("go.mod")) {
    return {
      command: filter ? `go test ./... -run "${filter}"` : "go test ./...",
      evidence: "go.mod",
    };
  }
  const unittest = unittestLayout(root);
  if (unittest) {
    return {
      command: filter ? `${unittest.command} -k "${filter}"` : unittest.command,
      evidence: unittest.evidence,
    };
  }
  return null;
}

export type TypecheckMode = "off" | "record" | "enforce";

/** NEXUS_TYPECHECK (off | enforce) overrides the configured mode; a configured verifier makes the check record-only by default. */
export function typecheckMode(configured: TypecheckMode | undefined, hasConfiguredVerifier: boolean): TypecheckMode {
  const env = process.env.NEXUS_TYPECHECK?.trim().toLowerCase();
  if (env === "off" || env === "enforce") return env;
  return configured ?? (hasConfiguredVerifier ? "record" : "enforce");
}

export interface DiscoveredTypecheck {
  tool: "tsc" | "cargo" | "go" | "pyright" | "mypy";
  /** The tool is on no search path the check would use here: reported UNAVAILABLE without running or asking approval. */
  missingTool?: boolean;
  /** Prints the tool version; run as its own call so no shell operator is assumed. */
  probe: string;
  command: string;
  /** Workspace-relative configuration file the check ran under. */
  configPath: string;
  /** Workspace-relative project directory, including for projects nested inside a monorepo. */
  projectRoot?: string;
  configSha256: string;
  /** Hash of the resolved tool launcher, so an approval binds to the binary that runs. */
  toolSha256?: string;
  /** Set when the configuration is not one a type-check can stand for (e.g. a solution-style tsconfig). */
  skipReason?: string;
  /** Discovery hit a hard safety cap, so the set of project checks is incomplete. */
  discoveryIncomplete?: boolean;
}

const sha256File = (file: string): string | undefined => {
  try {
    return createHash("sha256").update(fs.readFileSync(fs.realpathSync(file))).digest("hex");
  } catch {
    return undefined;
  }
};

function resolveOnPath(name: string): string | undefined {
  for (const dir of (process.env.PATH ?? "").split(path.delimiter)) {
    if (!dir) continue;
    const candidate = path.join(dir, name);
    try {
      fs.accessSync(candidate, fs.constants.X_OK);
      return candidate;
    } catch {}
  }
  return undefined;
}

const shellQuote = (value: string) => `'${value.replaceAll("'", "'\\''")}'`;
const shellPath = (value: string) => /^[A-Za-z0-9_./-]+$/.test(value) ? value : shellQuote(value);

/** Discover one check per configured project, including nested packages in a monorepo. */
export function discoverTypechecks(workspace: string): DiscoveredTypecheck[] {
  const root = path.resolve(workspace);
  const result: DiscoveredTypecheck[] = [];
  const ignored = new Set([".git", "node_modules", "target", "dist", "build", "coverage", ".venv", "venv", "vendor"]);
  const queue = [root];
  const seen = new Set<string>();
  // Bound repository-controlled traversal. If this limit is reached, callers get all checks found so far;
  // the explicit cap prevents a generated or hostile workspace from turning verification into an unbounded scan.
  const maxDirectories = 20_000;
  const maxChecks = 32;
  let capped = false;
  while (queue.length && seen.size < maxDirectories) {
    const project = queue.shift()!;
    let real: string;
    try { real = fs.realpathSync(project); } catch { continue; }
    if (seen.has(real) || (real !== root && !real.startsWith(`${root}${path.sep}`))) continue;
    seen.add(real);
    const checks = discoverTypechecksAtRoot(root, project);
    if (checks.length) {
      const available = maxChecks - result.length;
      result.push(...checks.slice(0, available));
      if (checks.length > available) { capped = true; break; }
    }
    let entries: fs.Dirent[];
    try { entries = fs.readdirSync(project, { withFileTypes: true }); } catch { continue; }
    for (const entry of entries) {
      if (!entry.isDirectory() || ignored.has(entry.name)) continue;
      queue.push(path.join(project, entry.name));
    }
  }
  if (queue.length) capped = true;
  if (capped) result.push({ tool: "tsc", probe: "", command: "<bounded project discovery>", configPath: "<workspace project scan>", configSha256: "", skipReason: "workspace contains more projects than the bounded type-check discovery limit permits", discoveryIncomplete: true });
  return result;
}

/** Compatibility helper for callers that need the workspace-root project's check. */
export function discoverTypecheck(workspace: string): DiscoveredTypecheck | null {
  const root = path.resolve(workspace);
  return discoverTypecheckAtRoot(root, root) ?? discoverTypecheckAtRoot(root, path.join(root, "core"));
}

function discoverTypecheckAtRoot(root: string, project: string): DiscoveredTypecheck | null {
  return discoverTypechecksAtRoot(root, project)[0] ?? null;
}

function discoverTypechecksAtRoot(root: string, project: string): DiscoveredTypecheck[] {
  const projectRelative = path.relative(root, project).split(path.sep).join("/");
  const prefix = projectRelative ? `cd ${shellQuote(projectRelative)} && ` : "";
  const read = (rel: string): string | null => {
    try {
      return fs.readFileSync(path.join(project, rel), "utf-8");
    } catch {
      return null;
    }
  };

