421	/** UNAVAILABLE: the tool is not installed here, so nothing was checked (never a pass). */
422	export type TypecheckStatus = "PASSED" | "FAILED" | "TIMED_OUT" | "ENVIRONMENT" | "PREEXISTING" | "UNAVAILABLE";
423	
424	export interface TypecheckRun {
425	  status: TypecheckStatus;
426	  exitCode: number | null;
427	  version?: string;
428	  output: string;
429	  errorCount?: number;
430	  firstDiagnostics?: string[];
431	  /** Errors not present in the baseline run (only when a baseline was supplied). */
432	  introducedCount?: number;
433	  /** Every located error, as `file<NL>message` signatures; what a baseline stores. */
434	  signatures?: string[];
435	}
