439	/** A located error's identity across runs: the file relative to the workspace and the message, never the line (edits move it). */
440	export function typecheckSignatures(check: Pick<DiscoveredTypecheck, "configPath">, output: string, workspace: string): string[] {
441	  const root = path.resolve(workspace);
442	  const bases = [root, path.resolve(root, path.dirname(check.configPath))];
443	  return parseTypecheckDiagnostics(output).located.map(({ file, text }) => {
444	    const abs = path.isAbsolute(file) ? file : path.resolve(bases[1], file);
445	    const rel = path.relative(root, abs);
446	    return `${rel.startsWith("..") ? file : rel}\n${text}`;
447	  });
448	}
