450	/**
451	 * Decide what a non-zero check means. It blocks (FAILED) when an error is located in a file the candidate modified, or,
452	 * given a `baseline` (the signatures present before the change), when any error is new (a caller broken in an untouched
453	 * file). Errors only in untouched files that the baseline already had are PREEXISTING; output that cannot be attributed
454	 * is ENVIRONMENT.
455	 */
456	export function classifyTypecheck(
457	  check: Pick<DiscoveredTypecheck, "tool" | "configPath">,
458	  output: string,
459	  workspace: string,
460	  modified: ReadonlySet<string>,
461	  baseline?: ReadonlySet<string>,
462	): { status: "FAILED" | "ENVIRONMENT" | "PREEXISTING"; diagnostics: TypecheckDiagnostics; introducedCount?: number; signatures: string[] } {
463	  const diagnostics = parseTypecheckDiagnostics(output);
464	  // No located error: configuration (TS5xxx/TS6xxx), missing type packages, dependency resolution, offline or lockfile
465	  // failures. These say the check could not run here, not that the candidate broke it.
466	  if (diagnostics.files.length === 0) return { status: "ENVIRONMENT", diagnostics, signatures: [] };
467	  const signatures = typecheckSignatures(check, output, workspace);
468	  const introduced = baseline ? signatures.filter((sig) => !baseline.has(sig)).length : undefined;
469	  const root = path.resolve(workspace);
470	  const bases = [root, path.resolve(root, path.dirname(check.configPath))];
471	  const real = (f: string) => {
472	    try {
473	      return fs.realpathSync(f);
474	    } catch {
475	      return f;
476	    }
477	  };
478	  const touched = new Set<string>();
479	  for (const m of modified) {
480	    touched.add(path.resolve(m));
481	    touched.add(real(m));
482	  }
483	  const hit = diagnostics.files.some((f) => bases.some((b) => {
484	    const abs = path.resolve(b, f);
485	    return touched.has(abs) || touched.has(real(abs));
486	  }));
487	  return { status: hit || (introduced ?? 0) > 0 ? "FAILED" : "PREEXISTING", diagnostics, signatures, ...(introduced !== undefined ? { introducedCount: introduced } : {}) };
488	}
