490	export async function runTypecheck(
491	  check: DiscoveredTypecheck,
492	  execute: TimedExecutor,
493	  workspace: string,
494	  modified: ReadonlySet<string>,
495	  budgetSecs: number,
496	  baseline?: ReadonlySet<string>,
497	): Promise<TypecheckRun> {
498	  const PROBE_SECS = 30;
499	  let version: string | undefined;
500	  if (check.missingTool) return { status: "UNAVAILABLE", exitCode: null, output: `${check.tool} is not installed here` };
501	  try {
502	    const probe = parseExecution(await execute(check.probe, Math.min(PROBE_SECS, budgetSecs)));
503	    if (!probe.succeeded) return { status: probe.exitCode === 126 || probe.exitCode === 127 ? "UNAVAILABLE" : "ENVIRONMENT", exitCode: probe.exitCode ?? null, output: probe.rawOutput };
504	    const line = probe.rawOutput.split("\n")[0]?.trim() ?? "";
505	    if (/\d+\.\d+/.test(line)) version = line.slice(0, 100);
506	  } catch (error: any) {
507	    return { status: "ENVIRONMENT", exitCode: null, output: String(error?.message ?? error) };
508	  }
509	  let run: ReturnType<typeof parseExecution>;
510	  try {
511	    run = parseExecution(await execute(check.command, budgetSecs));
512	  } catch (error: any) {
513	    return { status: "ENVIRONMENT", exitCode: null, version, output: String(error?.message ?? error) };
514	  }
515	  const base = { exitCode: run.exitCode ?? null, version, output: run.rawOutput };
516	  if (run.timedOut) return { ...base, status: "TIMED_OUT" };
517	  if (run.succeeded) return { ...base, status: "PASSED" };
518	  if (run.exitCode === undefined || run.exitCode === null || run.exitCode === 126 || run.exitCode === 127) return { ...base, status: "ENVIRONMENT" };
519	  const { status, diagnostics, introducedCount, signatures } = classifyTypecheck(check, run.rawOutput, workspace, modified, baseline);
520	  return {
521	    ...base,
522	    status,
523	    errorCount: diagnostics.errorCount,
524	    firstDiagnostics: diagnostics.first,
525	    signatures,
526	    ...(introducedCount !== undefined ? { introducedCount } : {}),
527	  };
528	}
