636	const VERIFIER_OUTPUT_TAIL_BYTES = 4 * 1024 * 1024;
637	const VERIFIER_PASSTHROUGH_DEFAULT = [
638	  "CARGO_HOME", "RUSTUP_HOME", "RUSTUP_TOOLCHAIN", "GOPATH", "GOCACHE", "GOFLAGS", "GOROOT", "GOMODCACHE",
639	  "NODE_OPTIONS", "NVM_DIR", "VOLTA_HOME", "PYENV_ROOT", "VIRTUAL_ENV", "PYTHONPATH", "JAVA_HOME", "CI",
640	  "XDG_CACHE_HOME", "LD_LIBRARY_PATH", "UV_*", "GRADLE_*", "MAVEN_*", "DOTNET_*",
641	];
642	const SECRET_NAME = /KEY|TOKEN|SECRET|PASSWORD|CREDENTIAL/i;
643	const TOOLCHAIN_HINT_NAME = /^(NEXUS_|ANSIBLE_|PIP_|NPM_|CONDA_|RUBY|GEM_|BUNDLE_|PYTHON|CARGO_|RUST|GO[A-Z]|JAVA|NODE_|PNPM_|YARN_)/;
644	
645	function passthroughMatches(name: string, patterns: string[]): boolean {
646	  return patterns.some((pattern) => (pattern.endsWith("*") ? name.startsWith(pattern.slice(0, -1)) : name === pattern));
647	}
