649	/**
650	 * The environment of a verifier child: the MCP allowlist, a default toolchain list (never a name that looks like a
651	 * secret), and the names the operator opted in with NEXUS_VERIFIER_ENV_PASSTHROUGH (comma-separated, a trailing `*`
652	 * is a prefix). That setting is read as an operator setting, never from a project .env; a NEXUS_* variable passes only
653	 * when the operator names it there. Only inherited environment variables are scrubbed: files under HOME (config.env,
654	 * .ssh, .aws, .npmrc, .netrc, .cargo/credentials.toml) stay readable to the verifier.
655	 */
656	export function buildVerifierEnvironment(): Record<string, string> {
657	  const env = buildMcpEnvironment();
658	  const optIn = (operatorSetting("NEXUS_VERIFIER_ENV_PASSTHROUGH") ?? "").split(",").map((n) => n.trim()).filter(Boolean);
659	  for (const [name, value] of Object.entries(process.env)) {
660	    if (value === undefined || name in env) continue;
661	    if (passthroughMatches(name, optIn) || (passthroughMatches(name, VERIFIER_PASSTHROUGH_DEFAULT) && !SECRET_NAME.test(name))) {
662	      env[name] = value;
663	    }
664	  }
665	  return env;
666	}
