668	/** Names (never values) of toolchain-looking variables the parent has but the verifier did not receive. */
669	export function withheldToolchainNames(env: Record<string, string> = buildVerifierEnvironment()): string[] {
670	  return Object.keys(process.env)
671	    .filter((name) => !(name in env) && TOOLCHAIN_HINT_NAME.test(name) && !SECRET_NAME.test(name))
672	    .sort()
673	    .slice(0, 12);
674	}
