676	export function environmentHint(): string {
677	  const withheld = withheldToolchainNames();
678	  return "environment: command not found. The verifier runs with a scrubbed environment (inherited variables only); " +
679	    "add names to NEXUS_VERIFIER_ENV_PASSTHROUGH (comma-separated, trailing * for a prefix)." +
680	    (withheld.length ? ` Set here but not passed: ${withheld.join(", ")}.` : "");
681	}
