689	/**
690	 * Run an already approved verifier command line outside the tool runner. The line is one `bash -c` argument, so it is
691	 * the only thing that executes. The child gets the verifier environment (see buildVerifierEnvironment), no stdin, and
692	 * a hard deadline: `timeout -s KILL` signals its whole process group, so grandchildren do not outlive it (without the
693	 * `timeout` binary only bash is killed). Output goes to a file and the LAST bytes are kept.
694	 */
695	export function runVerifierShell(command: string, cwd: string, timeoutMs: number): VerifierShellResult {
696	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-verifier-"));
697	  const file = path.join(dir, "out");
698	  const fd = fs.openSync(file, "w+");
699	  try {
700	    const wrapped = hasTimeoutBinary();
701	    const started = Date.now();
702	    const ran = spawnSync(
703	      wrapped ? "timeout" : "bash",
704	      wrapped ? ["-s", "KILL", `${Math.max(timeoutMs, 1) / 1000}s`, "bash", "-c", command] : ["-c", command],
705	      { cwd, env: buildVerifierEnvironment(), stdio: ["ignore", fd, fd], timeout: timeoutMs + 5000, killSignal: "SIGKILL" },
706	    );
707	    const size = fs.fstatSync(fd).size;
708	    const length = Math.min(size, VERIFIER_OUTPUT_TAIL_BYTES);
709	    const buffer = Buffer.alloc(length);
710	    fs.readSync(fd, buffer, 0, length, size - length);
711	    const truncated = size > length;
712	    const timedOut =
713	      (ran.error as NodeJS.ErrnoException | undefined)?.code === "ETIMEDOUT" ||
714	      (wrapped && (ran.status === 137 || ran.signal === "SIGKILL") && Date.now() - started >= timeoutMs - 50);
715	    const spawnFailure = ran.error && !timedOut ? `${ran.error.message}\n` : "";
716	    const exitCode = ran.error ? null : ran.status;
717	    return {
718	      success: !ran.error && ran.status === 0,
719	      timedOut,
720	      exitCode,
721	      truncated,
722	      output: `${spawnFailure}${truncated ? `[output truncated: last ${length} of ${size} bytes]\n` : ""}${buffer.toString("utf-8")}`,
723	    };
724	  } finally {
725	    fs.closeSync(fd);
726	    fs.rmSync(dir, { recursive: true, force: true });
727	  }
728	}
