/** UNAVAILABLE: the tool is not installed here, so nothing was checked (never a pass). */
export type TypecheckStatus = "PASSED" | "FAILED" | "TIMED_OUT" | "ENVIRONMENT" | "PREEXISTING" | "UNAVAILABLE";

export interface TypecheckRun {
  status: TypecheckStatus;
  exitCode: number | null;
  version?: string;
  output: string;
  errorCount?: number;
  firstDiagnostics?: string[];
  /** Errors not present in the baseline run (only when a baseline was supplied). */
  introducedCount?: number;
  /** Every located error, as `file<NL>message` signatures; what a baseline stores. */
  signatures?: string[];
}

export type TimedExecutor = (command: string, timeoutSecs: number) => Promise<{ success: boolean; output: string; error?: string; timedOut?: boolean }>;

/** A located error's identity across runs: the file relative to the workspace and the message, never the line (edits move it). */
export function typecheckSignatures(check: Pick<DiscoveredTypecheck, "configPath">, output: string, workspace: string): string[] {
  const root = path.resolve(workspace);
  const bases = [root, path.resolve(root, path.dirname(check.configPath))];
  return parseTypecheckDiagnostics(output).located.map(({ file, text }) => {
    const abs = path.isAbsolute(file) ? file : path.resolve(bases[1], file);
    const rel = path.relative(root, abs);
    return `${rel.startsWith("..") ? file : rel}\n${text}`;
  });
}

/**
 * Decide what a non-zero check means. It blocks (FAILED) when an error is located in a file the candidate modified, or,
 * given a `baseline` (the signatures present before the change), when any error is new (a caller broken in an untouched
 * file). Errors only in untouched files that the baseline already had are PREEXISTING; output that cannot be attributed
 * is ENVIRONMENT.
 */
export function classifyTypecheck(
  check: Pick<DiscoveredTypecheck, "tool" | "configPath">,
  output: string,
  workspace: string,
  modified: ReadonlySet<string>,
  baseline?: ReadonlySet<string>,
): { status: "FAILED" | "ENVIRONMENT" | "PREEXISTING"; diagnostics: TypecheckDiagnostics; introducedCount?: number; signatures: string[] } {
  const diagnostics = parseTypecheckDiagnostics(output);
  // No located error: configuration (TS5xxx/TS6xxx), missing type packages, dependency resolution, offline or lockfile
  // failures. These say the check could not run here, not that the candidate broke it.
  if (diagnostics.files.length === 0) return { status: "ENVIRONMENT", diagnostics, signatures: [] };
  const signatures = typecheckSignatures(check, output, workspace);
  const introduced = baseline ? signatures.filter((sig) => !baseline.has(sig)).length : undefined;
  const root = path.resolve(workspace);
  const bases = [root, path.resolve(root, path.dirname(check.configPath))];
  const real = (f: string) => {
    try {
      return fs.realpathSync(f);
    } catch {
      return f;
    }
  };
  const touched = new Set<string>();
  for (const m of modified) {
    touched.add(path.resolve(m));
    touched.add(real(m));
  }
  const hit = diagnostics.files.some((f) => bases.some((b) => {
    const abs = path.resolve(b, f);
    return touched.has(abs) || touched.has(real(abs));
  }));
  return { status: hit || (introduced ?? 0) > 0 ? "FAILED" : "PREEXISTING", diagnostics, signatures, ...(introduced !== undefined ? { introducedCount: introduced } : {}) };
}

export async function runTypecheck(
  check: DiscoveredTypecheck,
  execute: TimedExecutor,
  workspace: string,
  modified: ReadonlySet<string>,
  budgetSecs: number,
  baseline?: ReadonlySet<string>,
): Promise<TypecheckRun> {
  const PROBE_SECS = 30;
  let version: string | undefined;
  if (check.missingTool) return { status: "UNAVAILABLE", exitCode: null, output: `${check.tool} is not installed here` };
  try {
    const probe = parseExecution(await execute(check.probe, Math.min(PROBE_SECS, budgetSecs)));
    if (!probe.succeeded) return { status: probe.exitCode === 126 || probe.exitCode === 127 ? "UNAVAILABLE" : "ENVIRONMENT", exitCode: probe.exitCode ?? null, output: probe.rawOutput };
    const line = probe.rawOutput.split("\n")[0]?.trim() ?? "";
    if (/\d+\.\d+/.test(line)) version = line.slice(0, 100);
  } catch (error: any) {
    return { status: "ENVIRONMENT", exitCode: null, output: String(error?.message ?? error) };
  }
  let run: ReturnType<typeof parseExecution>;
  try {
    run = parseExecution(await execute(check.command, budgetSecs));
  } catch (error: any) {
    return { status: "ENVIRONMENT", exitCode: null, version, output: String(error?.message ?? error) };
  }
  const base = { exitCode: run.exitCode ?? null, version, output: run.rawOutput };
  if (run.timedOut) return { ...base, status: "TIMED_OUT" };
  if (run.succeeded) return { ...base, status: "PASSED" };
  if (run.exitCode === undefined || run.exitCode === null || run.exitCode === 126 || run.exitCode === 127) return { ...base, status: "ENVIRONMENT" };
  const { status, diagnostics, introducedCount, signatures } = classifyTypecheck(check, run.rawOutput, workspace, modified, baseline);
  return {
    ...base,
    status,
    errorCount: diagnostics.errorCount,
    firstDiagnostics: diagnostics.first,
    signatures,
    ...(introducedCount !== undefined ? { introducedCount } : {}),
  };
}

export interface VerifierDescription {
  command: string;
  evidence: string;
  script?: string;
  digest: string;
}

/**
 * Resolves the verifier command, its justifying evidence, and its script body (e.g. from
 * package.json scripts.test or Makefile test: recipe), plus a digest for approval caching.
 */
export function describeVerifier(workspace: string, commandOverride?: string): VerifierDescription | null {
  const root = path.resolve(workspace);
  const has = (p: string) => fs.existsSync(path.join(root, p));
  let command = commandOverride?.trim();
  let evidence = "configured";
  let script: string | undefined;

  if (!command) {
    const discovered = discoverVerifier(workspace);
    if (!discovered) return null;
    command = discovered.command;
    evidence = discovered.evidence;
  }

  // Look up script body based on command and workspace files
  if (command === "npm test" || command.startsWith("npm test") || command.startsWith("npm --prefix")) {
    let pkgRel = "package.json";
    if (command.includes("--prefix")) {
      const match = command.match(/--prefix\s+([^\s]+)/);
      if (match) pkgRel = path.join(match[1], "package.json");
    }
    try {
      const pkg = JSON.parse(fs.readFileSync(path.join(root, pkgRel), "utf-8"));
      script = pkg?.scripts?.test;
      if (evidence === "configured") evidence = `${pkgRel}:scripts.test`;
    } catch {}
  } else if (command === "make test" || command.startsWith("make test")) {
    try {
      const content = fs.readFileSync(path.join(root, "Makefile"), "utf-8");
      const match = content.match(/^test:[^\n]*\n((?:\t[^\n]*\n?)+)/m);
      if (match) {
        script = match[1].trim();
        if (evidence === "configured") evidence = "Makefile:test";
      }
    } catch {}
  } else if (command === "cargo test" || command.startsWith("cargo test")) {
    try {
      let cargoRel = "Cargo.toml";
      if (command.includes("--manifest-path")) {
        const match = command.match(/--manifest-path\s+([^\s]+)/);
        if (match) cargoRel = match[1];
      }
      if (fs.existsSync(path.join(root, cargoRel))) {
        script = fs.readFileSync(path.join(root, cargoRel), "utf-8");
        if (evidence === "configured") evidence = cargoRel;
      }
    } catch {}
  } else if (command === "pytest" || command.startsWith("pytest")) {
    for (const p of ["pytest.ini", "pyproject.toml", "setup.cfg"]) {
      if (has(p)) {
        try {
          script = fs.readFileSync(path.join(root, p), "utf-8");
          if (evidence === "configured") evidence = p;
          break;
        } catch {}
      }
    }
  }

  if (script === undefined) {
    // If command runs a local script file (e.g. node script.js or ./test.sh), try reading it
    const parts = command.split(/\s+/);
    for (const part of parts.slice(1)) {
      if (!part.startsWith("-") && has(part)) {
        try {
          const stat = fs.statSync(path.join(root, part));
          if (stat.isFile() && stat.size < 50_000) {
            script = fs.readFileSync(path.join(root, part), "utf-8");
            break;
          }
        } catch {}
      }
    }
    if (script === undefined) script = command;
  }

  const digest = createHash("sha256").update(`${command}\n${script}`).digest("hex");
  return {
    command,
    evidence,
    script,
    digest,
  };
}

export interface VerifierShellResult {
  success: boolean;
  timedOut: boolean;
  /** The command's exit status; null when it was killed by a signal or never started. */
  exitCode: number | null;
  output: string;
  /** The output exceeded the capture limit: `output` holds the last bytes only. */
  truncated: boolean;
}

const VERIFIER_OUTPUT_TAIL_BYTES = 4 * 1024 * 1024;
const VERIFIER_PASSTHROUGH_DEFAULT = [
  "CARGO_HOME", "RUSTUP_HOME", "RUSTUP_TOOLCHAIN", "GOPATH", "GOCACHE", "GOFLAGS", "GOROOT", "GOMODCACHE",
  "NODE_OPTIONS", "NVM_DIR", "VOLTA_HOME", "PYENV_ROOT", "VIRTUAL_ENV", "PYTHONPATH", "JAVA_HOME", "CI",
  "XDG_CACHE_HOME", "LD_LIBRARY_PATH", "UV_*", "GRADLE_*", "MAVEN_*", "DOTNET_*",
];
const SECRET_NAME = /KEY|TOKEN|SECRET|PASSWORD|CREDENTIAL/i;
const TOOLCHAIN_HINT_NAME = /^(NEXUS_|ANSIBLE_|PIP_|NPM_|CONDA_|RUBY|GEM_|BUNDLE_|PYTHON|CARGO_|RUST|GO[A-Z]|JAVA|NODE_|PNPM_|YARN_)/;

function passthroughMatches(name: string, patterns: string[]): boolean {
  return patterns.some((pattern) => (pattern.endsWith("*") ? name.startsWith(pattern.slice(0, -1)) : name === pattern));
}

/**
 * The environment of a verifier child: the MCP allowlist, a default toolchain list (never a name that looks like a
 * secret), and the names the operator opted in with NEXUS_VERIFIER_ENV_PASSTHROUGH (comma-separated, a trailing `*`
 * is a prefix). That setting is read as an operator setting, never from a project .env; a NEXUS_* variable passes only
 * when the operator names it there. Only inherited environment variables are scrubbed: files under HOME (config.env,
 * .ssh, .aws, .npmrc, .netrc, .cargo/credentials.toml) stay readable to the verifier.
 */
export function buildVerifierEnvironment(): Record<string, string> {
  const env = buildMcpEnvironment();
  const optIn = (operatorSetting("NEXUS_VERIFIER_ENV_PASSTHROUGH") ?? "").split(",").map((n) => n.trim()).filter(Boolean);
  for (const [name, value] of Object.entries(process.env)) {
    if (value === undefined || name in env) continue;
    if (passthroughMatches(name, optIn) || (passthroughMatches(name, VERIFIER_PASSTHROUGH_DEFAULT) && !SECRET_NAME.test(name))) {
      env[name] = value;
    }
  }
  return env;
}

/** Names (never values) of toolchain-looking variables the parent has but the verifier did not receive. */
export function withheldToolchainNames(env: Record<string, string> = buildVerifierEnvironment()): string[] {
  return Object.keys(process.env)
    .filter((name) => !(name in env) && TOOLCHAIN_HINT_NAME.test(name) && !SECRET_NAME.test(name))
    .sort()
    .slice(0, 12);
}

export function environmentHint(): string {
  const withheld = withheldToolchainNames();
  return "environment: command not found. The verifier runs with a scrubbed environment (inherited variables only); " +
    "add names to NEXUS_VERIFIER_ENV_PASSTHROUGH (comma-separated, trailing * for a prefix)." +
    (withheld.length ? ` Set here but not passed: ${withheld.join(", ")}.` : "");
}

let timeoutBinary: boolean | undefined;
function hasTimeoutBinary(): boolean {
  timeoutBinary ??= spawnSync("timeout", ["--version"], { stdio: "ignore" }).status === 0;
  return timeoutBinary;
}

/**
 * Run an already approved verifier command line outside the tool runner. The line is one `bash -c` argument, so it is
 * the only thing that executes. The child gets the verifier environment (see buildVerifierEnvironment), no stdin, and
 * a hard deadline: `timeout -s KILL` signals its whole process group, so grandchildren do not outlive it (without the
 * `timeout` binary only bash is killed). Output goes to a file and the LAST bytes are kept.
 */
export function runVerifierShell(command: string, cwd: string, timeoutMs: number): VerifierShellResult {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-verifier-"));
  const file = path.join(dir, "out");
  const fd = fs.openSync(file, "w+");
  try {
    const wrapped = hasTimeoutBinary();
    const started = Date.now();
    const ran = spawnSync(
      wrapped ? "timeout" : "bash",
      wrapped ? ["-s", "KILL", `${Math.max(timeoutMs, 1) / 1000}s`, "bash", "-c", command] : ["-c", command],
      { cwd, env: buildVerifierEnvironment(), stdio: ["ignore", fd, fd], timeout: timeoutMs + 5000, killSignal: "SIGKILL" },
    );
    const size = fs.fstatSync(fd).size;
    const length = Math.min(size, VERIFIER_OUTPUT_TAIL_BYTES);
    const buffer = Buffer.alloc(length);
    fs.readSync(fd, buffer, 0, length, size - length);
    const truncated = size > length;
    const timedOut =
      (ran.error as NodeJS.ErrnoException | undefined)?.code === "ETIMEDOUT" ||
      (wrapped && (ran.status === 137 || ran.signal === "SIGKILL") && Date.now() - started >= timeoutMs - 50);
    const spawnFailure = ran.error && !timedOut ? `${ran.error.message}\n` : "";
    const exitCode = ran.error ? null : ran.status;
    return {
      success: !ran.error && ran.status === 0,
      timedOut,
      exitCode,
      truncated,
      output: `${spawnFailure}${truncated ? `[output truncated: last ${length} of ${size} bytes]\n` : ""}${buffer.toString("utf-8")}`,
    };
  } finally {
    fs.closeSync(fd);
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

/**
 * Execute automated test suite with diagnostic error parsing (Candidate #47)
 */
export function runTestSuite(workspace: string, filterPattern?: string): TestRunResult {
  const root = path.resolve(workspace);
  const discovered = discoverVerifier(root, filterPattern);
  if (!discovered) {
    return summarizeTestRun("none", false, "no verifier: no verification command is configured or discovered in this workspace.");
  }
  const command = discovered.command;

  const ran = runVerifierShell(command, root, verifierTimeoutSecs() * 1000);
  const rawOutput = ran.exitCode === 127 ? `${ran.output}\n${environmentHint()}` : ran.output;
  const success = ran.success;

  return summarizeTestRun(command, success, rawOutput);
}

export interface ParsedExecution {
  succeeded: boolean;
  timedOut: boolean;
  /** Undefined when the runner returned no execution envelope (the command's exit status is then unknown). */
  exitCode?: number | null;
  rawOutput: string;
}

/** Unwrap the runner's envelope; a killed or timed-out command has `exit_code: null`. */
export function parseExecution(result: { success: boolean; output: string; error?: string; timedOut?: boolean }): ParsedExecution {
  let succeeded = false;
  let timedOut = result.timedOut === true;
  let exitCode: number | null | undefined;
  let rawOutput = [result.output, result.error].filter(Boolean).join("\n");
  if (result.success) {
    try {
      const execution = JSON.parse(result.output);
      if (execution && typeof execution === "object" && "exit_code" in execution) {
        timedOut = execution.timed_out === true;
        exitCode = typeof execution.exit_code === "number" ? execution.exit_code : null;
        succeeded = exitCode === 0 && !timedOut;
        rawOutput = [execution.stdout, execution.stderr, result.error].filter(Boolean).join("\n");
      }
    } catch {
      // Unknown executor output is not proof that the command exited successfully.
    }
  }
  return { succeeded, timedOut, exitCode, rawOutput };
}

/** Execute test discovery or an explicit verifier through the caller's mutation boundary. */
export async function runTestSuiteWithExecutor(
  workspace: string,
  execute: TestCommandExecutor,
  commandOverride?: string,
): Promise<TestRunResult> {
  const command = commandOverride?.trim() || discoverVerifier(workspace)?.command || "none";
  if (command === "none") return summarizeTestRun("none", false, "no verifier: no verification command is configured or discovered in this workspace.");
  try {
    const result = await execute(command);
    const { succeeded: commandSucceeded, timedOut, exitCode: parsedExit, rawOutput } = parseExecution(result);
    const exitCode = typeof parsedExit === "number" ? parsedExit : undefined;
    const summary = summarizeTestRun(command, commandSucceeded, rawOutput);
    const withExit = {
      ...summary,
      ...(exitCode === undefined ? {} : { exitCode }),
      ...(!result.success ? { executorFailed: true } : {}),
    };
    return timedOut ? { ...withExit, success: false, timedOut: true } : withExit;
  } catch (error: any) {
    return { ...summarizeTestRun(command, false, error?.message || "Verification command execution failed."), executorFailed: true };
  }
}

function summarizeTestRun(command: string, success: boolean, rawOutput: string): TestRunResult {
  // Extract failing test line summaries
  const failures: string[] = [];
  const lines = rawOutput.split("\n");
  for (const line of lines) {
    const trimmed = line.trim();
    if (
      trimmed.startsWith("FAIL") ||
      trimmed.startsWith("✖") ||
      (trimmed.includes("FAILED") && !trimmed.includes("0 failed")) ||
      trimmed.startsWith("test result: FAILED")
    ) {
      failures.push(trimmed);
    }
  }

  // Extract compiler/type diagnostics
  const diagnostics = extractCompilerDiagnostics(rawOutput);

  return {
    command,
    success,
    rawOutput,
    failures,
    diagnostics,
  };
}

/**
 * Whether a verifier command runs only part of the suite: a name filter (`-t`, `-k`, `--test-name-pattern`, `--grep`,
 * `-run`, `FILTER=`), a pytest node id (`file.py::test`), or a positional test name for `cargo test`. A filtered run
 * can show that a test passes, not that nothing else broke.
 */
export function isFilteredVerifierCommand(command: string): boolean {
  if (!command) return false;
  if (/(?:^|\s)(?:-t|-k|--grep|-g)(?:\s|=)\S/.test(command)) return true;
  if (/(?:^|\s)(?:--test-name-pattern|--testNamePattern|-run|--run)(?:\s|=)\S/.test(command)) return true;
  if (/(?:^|\s)FILTER=\S/.test(command)) return true;

