530	export interface VerifierDescription {
531	  command: string;
532	  evidence: string;
533	  script?: string;
534	  digest: string;
535	}
536	
537	/**
538	 * Resolves the verifier command, its justifying evidence, and its script body (e.g. from
539	 * package.json scripts.test or Makefile test: recipe), plus a digest for approval caching.
540	 */
541	export function describeVerifier(workspace: string, commandOverride?: string): VerifierDescription | null {
542	  const root = path.resolve(workspace);
543	  const has = (p: string) => fs.existsSync(path.join(root, p));
544	  let command = commandOverride?.trim();
545	  let evidence = "configured";
546	  let script: string | undefined;
547	
548	  if (!command) {
549	    const discovered = discoverVerifier(workspace);
550	    if (!discovered) return null;
551	    command = discovered.command;
552	    evidence = discovered.evidence;
553	  }
554	
555	  // Look up script body based on command and workspace files
556	  if (command === "npm test" || command.startsWith("npm test") || command.startsWith("npm --prefix")) {
557	    let pkgRel = "package.json";
558	    if (command.includes("--prefix")) {
559	      const match = command.match(/--prefix\s+([^\s]+)/);
560	      if (match) pkgRel = path.join(match[1], "package.json");
561	    }
562	    try {
563	      const pkg = JSON.parse(fs.readFileSync(path.join(root, pkgRel), "utf-8"));
564	      script = pkg?.scripts?.test;
565	      if (evidence === "configured") evidence = `${pkgRel}:scripts.test`;
566	    } catch {}
567	  } else if (command === "make test" || command.startsWith("make test")) {
568	    try {
569	      const content = fs.readFileSync(path.join(root, "Makefile"), "utf-8");
570	      const match = content.match(/^test:[^\n]*\n((?:\t[^\n]*\n?)+)/m);
571	      if (match) {
572	        script = match[1].trim();
573	        if (evidence === "configured") evidence = "Makefile:test";
574	      }
575	    } catch {}
576	  } else if (command === "cargo test" || command.startsWith("cargo test")) {
577	    try {
578	      let cargoRel = "Cargo.toml";
579	      if (command.includes("--manifest-path")) {
580	        const match = command.match(/--manifest-path\s+([^\s]+)/);
581	        if (match) cargoRel = match[1];
582	      }
583	      if (fs.existsSync(path.join(root, cargoRel))) {
584	        script = fs.readFileSync(path.join(root, cargoRel), "utf-8");
585	        if (evidence === "configured") evidence = cargoRel;
586	      }
587	    } catch {}
588	  } else if (command === "pytest" || command.startsWith("pytest")) {
589	    for (const p of ["pytest.ini", "pyproject.toml", "setup.cfg"]) {
590	      if (has(p)) {
591	        try {
592	          script = fs.readFileSync(path.join(root, p), "utf-8");
593	          if (evidence === "configured") evidence = p;
594	          break;
595	        } catch {}
596	      }
597	    }
598	  }
599	
600	  if (script === undefined) {
601	    // If command runs a local script file (e.g. node script.js or ./test.sh), try reading it
602	    const parts = command.split(/\s+/);
603	    for (const part of parts.slice(1)) {
604	      if (!part.startsWith("-") && has(part)) {
605	        try {
606	          const stat = fs.statSync(path.join(root, part));
607	          if (stat.isFile() && stat.size < 50_000) {
608	            script = fs.readFileSync(path.join(root, part), "utf-8");
609	            break;
610	          }
611	        } catch {}
612	      }
613	    }
614	    if (script === undefined) script = command;
615	  }
616	
617	  const digest = createHash("sha256").update(`${command}\n${script}`).digest("hex");
618	  return {
619	    command,
620	    evidence,
621	    script,
622	    digest,
623	  };
624	}
