626	export interface VerifierShellResult {
627	  success: boolean;
628	  timedOut: boolean;
629	  /** The command's exit status; null when it was killed by a signal or never started. */
630	  exitCode: number | null;
631	  output: string;
632	  /** The output exceeded the capture limit: `output` holds the last bytes only. */
633	  truncated: boolean;
634	}
635	
636	const VERIFIER_OUTPUT_TAIL_BYTES = 4 * 1024 * 1024;
637	const VERIFIER_PASSTHROUGH_DEFAULT = [
638	  "CARGO_HOME", "RUSTUP_HOME", "RUSTUP_TOOLCHAIN", "GOPATH", "GOCACHE", "GOFLAGS", "GOROOT", "GOMODCACHE",
639	  "NODE_OPTIONS", "NVM_DIR", "VOLTA_HOME", "PYENV_ROOT", "VIRTUAL_ENV", "PYTHONPATH", "JAVA_HOME", "CI",
640	  "XDG_CACHE_HOME", "LD_LIBRARY_PATH", "UV_*", "GRADLE_*", "MAVEN_*", "DOTNET_*",
641	];
642	const SECRET_NAME = /KEY|TOKEN|SECRET|PASSWORD|CREDENTIAL/i;
643	const TOOLCHAIN_HINT_NAME = /^(NEXUS_|ANSIBLE_|PIP_|NPM_|CONDA_|RUBY|GEM_|BUNDLE_|PYTHON|CARGO_|RUST|GO[A-Z]|JAVA|NODE_|PNPM_|YARN_)/;
644	
645	function passthroughMatches(name: string, patterns: string[]): boolean {
646	  return patterns.some((pattern) => (pattern.endsWith("*") ? name.startsWith(pattern.slice(0, -1)) : name === pattern));
647	}
648	
649	/**
650	 * The environment of a verifier child: the MCP allowlist, a default toolchain list (never a name that looks like a
651	 * secret), and the names the operator opted in with NEXUS_VERIFIER_ENV_PASSTHROUGH (comma-separated, a trailing `*`
652	 * is a prefix). That setting is read as an operator setting, never from a project .env; a NEXUS_* variable passes only
653	 * when the operator names it there. Only inherited environment variables are scrubbed: files under HOME (config.env,
654	 * .ssh, .aws, .npmrc, .netrc, .cargo/credentials.toml) stay readable to the verifier.
655	 */
656	export function buildVerifierEnvironment(): Record<string, string> {
657	  const env = buildMcpEnvironment();
658	  const optIn = (operatorSetting("NEXUS_VERIFIER_ENV_PASSTHROUGH") ?? "").split(",").map((n) => n.trim()).filter(Boolean);
659	  for (const [name, value] of Object.entries(process.env)) {
660	    if (value === undefined || name in env) continue;
661	    if (passthroughMatches(name, optIn) || (passthroughMatches(name, VERIFIER_PASSTHROUGH_DEFAULT) && !SECRET_NAME.test(name))) {
662	      env[name] = value;
663	    }
664	  }
665	  return env;
666	}
667	
668	/** Names (never values) of toolchain-looking variables the parent has but the verifier did not receive. */
669	export function withheldToolchainNames(env: Record<string, string> = buildVerifierEnvironment()): string[] {
670	  return Object.keys(process.env)
671	    .filter((name) => !(name in env) && TOOLCHAIN_HINT_NAME.test(name) && !SECRET_NAME.test(name))
672	    .sort()
673	    .slice(0, 12);
674	}
675	
676	export function environmentHint(): string {
677	  const withheld = withheldToolchainNames();
678	  return "environment: command not found. The verifier runs with a scrubbed environment (inherited variables only); " +
679	    "add names to NEXUS_VERIFIER_ENV_PASSTHROUGH (comma-separated, trailing * for a prefix)." +
680	    (withheld.length ? ` Set here but not passed: ${withheld.join(", ")}.` : "");
681	}
682	
683	let timeoutBinary: boolean | undefined;
684	function hasTimeoutBinary(): boolean {
685	  timeoutBinary ??= spawnSync("timeout", ["--version"], { stdio: "ignore" }).status === 0;
686	  return timeoutBinary;
687	}
688	
689	/**
690	 * Run an already approved verifier command line outside the tool runner. The line is one `bash -c` argument, so it is
691	 * the only thing that executes. The child gets the verifier environment (see buildVerifierEnvironment), no stdin, and
692	 * a hard deadline: `timeout -s KILL` signals its whole process group, so grandchildren do not outlive it (without the
693	 * `timeout` binary only bash is killed). Output goes to a file and the LAST bytes are kept.
694	 */
695	export function runVerifierShell(command: string, cwd: string, timeoutMs: number): VerifierShellResult {
696	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-verifier-"));
697	  const file = path.join(dir, "out");
698	  const fd = fs.openSync(file, "w+");
699	  try {
700	    const wrapped = hasTimeoutBinary();
701	    const started = Date.now();
702	    const ran = spawnSync(
703	      wrapped ? "timeout" : "bash",
704	      wrapped ? ["-s", "KILL", `${Math.max(timeoutMs, 1) / 1000}s`, "bash", "-c", command] : ["-c", command],
705	      { cwd, env: buildVerifierEnvironment(), stdio: ["ignore", fd, fd], timeout: timeoutMs + 5000, killSignal: "SIGKILL" },
706	    );
707	    const size = fs.fstatSync(fd).size;
708	    const length = Math.min(size, VERIFIER_OUTPUT_TAIL_BYTES);
709	    const buffer = Buffer.alloc(length);
710	    fs.readSync(fd, buffer, 0, length, size - length);
711	    const truncated = size > length;
712	    const timedOut =
713	      (ran.error as NodeJS.ErrnoException | undefined)?.code === "ETIMEDOUT" ||
714	      (wrapped && (ran.status === 137 || ran.signal === "SIGKILL") && Date.now() - started >= timeoutMs - 50);
715	    const spawnFailure = ran.error && !timedOut ? `${ran.error.message}\n` : "";
716	    const exitCode = ran.error ? null : ran.status;
717	    return {
718	      success: !ran.error && ran.status === 0,
719	      timedOut,
720	      exitCode,
721	      truncated,
722	      output: `${spawnFailure}${truncated ? `[output truncated: last ${length} of ${size} bytes]\n` : ""}${buffer.toString("utf-8")}`,
723	    };
724	  } finally {
725	    fs.closeSync(fd);
726	    fs.rmSync(dir, { recursive: true, force: true });
727	  }
728	}
