748	export interface ParsedExecution {
749	  succeeded: boolean;
750	  timedOut: boolean;
751	  /** Undefined when the runner returned no execution envelope (the command's exit status is then unknown). */
752	  exitCode?: number | null;
753	  rawOutput: string;
754	}
755	
756	/** Unwrap the runner's envelope; a killed or timed-out command has `exit_code: null`. */
757	export function parseExecution(result: { success: boolean; output: string; error?: string; timedOut?: boolean }): ParsedExecution {
758	  let succeeded = false;
759	  let timedOut = result.timedOut === true;
760	  let exitCode: number | null | undefined;
761	  let rawOutput = [result.output, result.error].filter(Boolean).join("\n");
762	  if (result.success) {
763	    try {
764	      const execution = JSON.parse(result.output);
765	      if (execution && typeof execution === "object" && "exit_code" in execution) {
766	        timedOut = execution.timed_out === true;
767	        exitCode = typeof execution.exit_code === "number" ? execution.exit_code : null;
768	        succeeded = exitCode === 0 && !timedOut;
769	        rawOutput = [execution.stdout, execution.stderr, result.error].filter(Boolean).join("\n");
770	      }
771	    } catch {
772	      // Unknown executor output is not proof that the command exited successfully.
773	    }
774	  }
775	  return { succeeded, timedOut, exitCode, rawOutput };
776	}
