778	/** Execute test discovery or an explicit verifier through the caller's mutation boundary. */
779	export async function runTestSuiteWithExecutor(
780	  workspace: string,
781	  execute: TestCommandExecutor,
782	  commandOverride?: string,
783	): Promise<TestRunResult> {
784	  const command = commandOverride?.trim() || discoverVerifier(workspace)?.command || "none";
785	  if (command === "none") return summarizeTestRun("none", false, "no verifier: no verification command is configured or discovered in this workspace.");
786	  try {
787	    const result = await execute(command);
788	    const { succeeded: commandSucceeded, timedOut, exitCode: parsedExit, rawOutput } = parseExecution(result);
789	    const exitCode = typeof parsedExit === "number" ? parsedExit : undefined;
790	    const summary = summarizeTestRun(command, commandSucceeded, rawOutput);
791	    const withExit = {
792	      ...summary,
793	      ...(exitCode === undefined ? {} : { exitCode }),
794	      ...(!result.success ? { executorFailed: true } : {}),
795	    };
796	    return timedOut ? { ...withExit, success: false, timedOut: true } : withExit;
797	  } catch (error: any) {
798	    return { ...summarizeTestRun(command, false, error?.message || "Verification command execution failed."), executorFailed: true };
799	  }
