802	function summarizeTestRun(command: string, success: boolean, rawOutput: string): TestRunResult {
803	  // Extract failing test line summaries
804	  const failures: string[] = [];
805	  const lines = rawOutput.split("\n");
806	  for (const line of lines) {
807	    const trimmed = line.trim();
808	    if (
809	      trimmed.startsWith("FAIL") ||
810	      trimmed.startsWith("✖") ||
811	      (trimmed.includes("FAILED") && !trimmed.includes("0 failed")) ||
812	      trimmed.startsWith("test result: FAILED")
813	    ) {
814	      failures.push(trimmed);
815	    }
816	  }
817	
818	  // Extract compiler/type diagnostics
819	  const diagnostics = extractCompilerDiagnostics(rawOutput);
820	
821	  return {
822	    command,
823	    success,
824	    rawOutput,
825	    failures,
826	    diagnostics,
827	  };
828	}
