830	/**
831	 * Whether a verifier command runs only part of the suite: a name filter (`-t`, `-k`, `--test-name-pattern`, `--grep`,
832	 * `-run`, `FILTER=`), a pytest node id (`file.py::test`), or a positional test name for `cargo test`. A filtered run
833	 * can show that a test passes, not that nothing else broke.
834	 */
835	export function isFilteredVerifierCommand(command: string): boolean {
836	  if (!command) return false;
837	  if (/(?:^|\s)(?:-t|-k|--grep|-g)(?:\s|=)\S/.test(command)) return true;
838	  if (/(?:^|\s)(?:--test-name-pattern|--testNamePattern|-run|--run)(?:\s|=)\S/.test(command)) return true;
839	  if (/(?:^|\s)FILTER=\S/.test(command)) return true;

840	  if (/\S\.py::\S/.test(command)) return true;
841	  if (/(?:^|\s)--(?:$|\s+[^-]\S*)/.test(command)) return true;
842	  const cargo = command.match(/\bcargo\s+test\b(.*)$/);
843	  if (cargo) {
844	    const tokens = cargo[1].trim().split(/\s+/).filter(Boolean);
845	    const takesValue = new Set(["--manifest-path", "-p", "--package", "--features", "-F", "--target", "--profile", "-j", "--jobs", "--bin", "--test", "--example", "--bench", "--exclude", "--target-dir", "--color", "--message-format"]);
846	    for (let i = 0; i < tokens.length; i++) {
847	      const token = tokens[i];
848	      if (token === "--") return tokens.slice(i + 1).some((t) => !t.startsWith("-"));
849	      if (takesValue.has(token)) {
850	        i++;
851	        continue;
852	      }
853	      if (token.startsWith("-") || /[;&|]/.test(token)) {
854	        if (/[;&|]/.test(token)) break;
855	        continue;
856	      }
857	      return true;
858	    }
859	  }
860	  return false;
861	}
