863	/**
864	 * Whether a test run's output shows that at least one test executed. Runners that report counts are read (node:test,
865	 * cargo, pytest, unittest, jest/vitest, mocha, go); output with no recognisable report — including no output — is not evidence.
866	 * Skipped tests are subtracted; a run where all tests were skipped returns false.
867	 */
868	export function hasExecutedTests(rawOutput: string): boolean {
869	  if (!rawOutput) return false;
870	
871	  // 1. node:test
872	  const nodeTests = [...rawOutput.matchAll(/ℹ\s+tests\s+(\d+)/g)];
873	  if (nodeTests.length) {
874	    const totalTests = nodeTests.reduce((sum, m) => sum + Number(m[1]), 0);
875	    const pass = [...rawOutput.matchAll(/ℹ\s+pass\s+(\d+)/g)].reduce((sum, m) => sum + Number(m[1]), 0);
876	    const fail = [...rawOutput.matchAll(/ℹ\s+fail\s+(\d+)/g)].reduce((sum, m) => sum + Number(m[1]), 0);
877	    const hasPassOrFail = /ℹ\s+(?:pass|fail)\s+\d+/.test(rawOutput);
878	    if (hasPassOrFail) return pass + fail > 0;
879	    const skipped = [...rawOutput.matchAll(/ℹ\s+skipped\s+(\d+)/g)].reduce((sum, m) => sum + Number(m[1]), 0);
880	    const todo = [...rawOutput.matchAll(/ℹ\s+todo\s+(\d+)/g)].reduce((sum, m) => sum + Number(m[1]), 0);
881	    return totalTests - skipped - todo > 0;
882	  }
883	
884	  // Node 20's default node:test reporter uses TAP summary lines; Node 22+ may emit the spec summary above.
885	  const nodeTap = rawOutput.match(
886	    /(?:^|\n)# tests (\d+)\r?\n# suites \d+\r?\n# pass (\d+)\r?\n# fail (\d+)\r?\n# cancelled (\d+)\r?\n# skipped (\d+)\r?\n# todo (\d+)(?:\r?\n# duration_ms [\d.]+)?(?=\r?\n|$)/
887	  );
888	  if (nodeTap) {
889	    const passed = Number(nodeTap[2]);
890	    const failed = Number(nodeTap[3]);
891	    return passed + failed > 0;
892	  }
893	
894	  // 2. Cargo (Rust)
895	  const cargo = [...rawOutput.matchAll(/test result: \w+\. (\d+) passed; (\d+) failed/g)];
896	  if (cargo.length) return cargo.some((m) => Number(m[1]) + Number(m[2]) > 0);
897	
898	  // 3. Jest
899	  const jest = rawOutput.match(/Tests:\s+(?:(\d+)\s+failed,?\s*)?(?:(\d+)\s+passed,?\s*)?(?:(\d+)\s+skipped,?\s*)?(\d+)\s+total/);
900	  if (jest) {
901	    const failed = Number(jest[1] || 0);
902	    const passed = Number(jest[2] || 0);
903	    return passed + failed > 0;
904	  }
905	
906	  // 4. Vitest
907	  const vitestPassed = rawOutput.match(/\bTests\s+.*?(\d+)\s+passed/);
908	  const vitestFailed = rawOutput.match(/\bTests\s+.*?(\d+)\s+failed/);
909	  if (vitestPassed || vitestFailed) {
910	    const passed = Number(vitestPassed ? vitestPassed[1] : 0);
911	    const failed = Number(vitestFailed ? vitestFailed[1] : 0);
912	    return passed + failed > 0;
913	  }
914	  if (/\bTests\s+\d+\s+skipped\b/.test(rawOutput) && !/\bTests\s+\d+\s+passed\b/.test(rawOutput)) {
915	    return false;
916	  }
917	
918	  // 5. Pytest
919	  if (/collected 0 items|no tests ran/i.test(rawOutput)) return false;
920	  const pytestPassed = rawOutput.match(/=+\s+.*?(\d+)\s+passed/);
921	  const pytestFailed = rawOutput.match(/=+\s+.*?(\d+)\s+failed/);
922	  if (pytestPassed || pytestFailed) {
923	    const passed = Number(pytestPassed ? pytestPassed[1] : 0);
924	    const failed = Number(pytestFailed ? pytestFailed[1] : 0);
925	    return passed + failed > 0;
926	  }
927	  if (/=+\s+\d+\s+skipped.*?=+/i.test(rawOutput)) return false;
928	
929	  // 6. Python unittest: "Ran 3 tests in 0.001s" (it also prints "Ran 0 tests" when discovery finds nothing)
930	  const unittest = [...rawOutput.matchAll(/^Ran (\d+) tests? in /gm)];
931	  if (unittest.length) {
932	    const totalRan = unittest.reduce((sum, m) => sum + Number(m[1]), 0);
933	    const skippedMatch = rawOutput.match(/OK\s*\((?:.*?,\s*)?skipped=(\d+)\)/);
934	    const skipped = skippedMatch ? Number(skippedMatch[1]) : 0;
935	    return totalRan - skipped > 0;
936	  }
937	
938	  // 7. Mocha
939	  const mochaPass = rawOutput.match(/^\s*(\d+)\s+passing\b/m);
940	  const mochaFail = rawOutput.match(/^\s*(\d+)\s+failing\b/m);
941	  if (mochaPass || mochaFail) {
942	    const passed = Number(mochaPass ? mochaPass[1] : 0);
943	    const failed = Number(mochaFail ? mochaFail[1] : 0);
944	    return passed + failed > 0;
945	  }
946	
947	  // 8. Go test: anchored regex ^ok\s+\S+\s+(\d+\.\d+s|\(cached\))
