138	function observedTestResults(output: string | undefined, testNames: ReadonlySet<string>): Map<string, "pass" | "fail"> {
139	  const results = new Map<string, "pass" | "fail">();
140	  if (!output || !testNames.size) return results;
141	  const text = output.replace(/\u001b(?:\[[0-9;?]*[ -/]*[@-~]|\][^\u0007\u001b]*(?:\u0007|\u001b\\))/g, "");
142	  for (const raw of text.split(/\r?\n/)) {
143	    const line = raw.trim();
144	    let name: string | undefined;
145	    let status: string | undefined;
146	    const tap = line.match(/^(ok|not ok)\s+\d+\s+-\s+(.+?)(?:\s+#\s*(SKIP|TODO)\b.*)?$/i);
147	    if (tap) {
148	      name = tap[2];
149	      status = tap[3] ? "skip" : tap[1].toLowerCase() === "ok" ? "pass" : "fail";
150	    }
151	    const spec = line.match(/^([✔✓√✖×✕])\s+(.+?)(?:\s+\([\d.]+\s*(?:ms|s)\))?$/);
152	    if (!name && spec) {
153	      name = spec[2];
154	      status = "✔✓√".includes(spec[1]) ? "pass" : "fail";
155	    }
156	    const pytest = line.match(/^(.+?)\s+(PASSED|FAILED|SKIPPED|XFAIL|XPASS)(?:\s+.*)?$/i);
157	    if (!name && pytest) {
158	      name = pytest[1];
159	      status = /^(PASSED)$/i.test(pytest[2]) ? "pass" : /^(FAILED)$/i.test(pytest[2]) ? "fail" : "skip";
160	    }
161	    const cargo = line.match(/^test\s+(\S+)\s+\.\.\.\s+(ok|FAILED|ignored)$/i);
162	    if (!name && cargo) {
163	      name = cargo[1];
164	      status = cargo[2].toLowerCase() === "ok" ? "pass" : cargo[2].toLowerCase() === "failed" ? "fail" : "skip";
165	    }
166	    const go = line.match(/^---\s+(PASS|FAIL|SKIP):\s+(\S+)/);
167	    if (!name && go) {
168	      name = go[2];
169	      status = go[1].toLowerCase() === "pass" ? "pass" : go[1].toLowerCase() === "fail" ? "fail" : "skip";
170	    }
171	    const unittest = line.match(/^(\S+(?:\s+\([^)]+\))?)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped(?:\s+.*)?)$/i);
172	    if (!name && unittest) {
173	      name = unittest[1];
174	      status = /^ok$/i.test(unittest[2]) ? "pass" : /^(FAIL|ERROR)$/i.test(unittest[2]) ? "fail" : "skip";
175	    }
176	    if (!name || !testNames.has(name)) continue;
177	    if (status === "fail") results.set(name, "fail");
178	    else if (status === "pass" && !results.has(name)) results.set(name, "pass");
179	  }
180	  return results;
