184	export function replayObligations(ledger: ObjectiveLedger, attempt: VerificationAttempt, output?: string): void {
185	  if (attempt.status === "SKIPPED_UNCHANGED_INPUTS" || attempt.status === "TIMED_OUT" || attempt.classification === "ENVIRONMENT" || attempt.filtered) return;
186	  const obligations = active(ledger).filter((ob) => ob.command === attempt.command);
187	  const observed = observedTestResults(output, new Set(obligations.map((ob) => ob.testName)));
188	  for (const ob of obligations) {
189	    const result = observed.get(ob.testName);
190	    const outcome = result ?? "unobserved";
191	    ob.replays.push({ attempt: attempt.n, at: attempt.at, outcome, ...(result ? { observedTestName: ob.testName } : {}) });
