1	/**
2	 * DV-3 regression obligations and the DV-4 reference gate.
3	 *
4	 * A confirmed failing test becomes a protected obligation only when the operator authorises it: nothing in the agent's
5	 * tool surface calls `authoriseObligation`; only operator commands do. The original failure record is immutable, so a
6	 * later minimisation keeps what was first seen. Each later verifier attempt of the obligation's command is a replay.
7	 * An edit that removes, skips or thins the obligation's test is recorded (never silently allowed, never blocked here).
8	 *
9	 * A replay passes only when the verifier output contains a recognised result line for the exact obligated test.
10	 * Overall suite success is not enough: the test may have been excluded or skipped. Pure data and pure functions; the
11	 * agent owns persistence.
12	 */
13	import type { ObjectiveLedger, VerificationAttempt } from "./objective.js";
14	import { normalizeOutcomeText } from "./execution_tracking.js";
15	
16	export interface RegressionObligation {
17	  id: string;
18	  /** The test as currently replayed (its original name until minimised). */
19	  testName: string;
20	  /** The verifier command whose attempts replay this obligation. */
21	  command: string;
22	  authorisedAt: string;
23	  /** The failure as first confirmed. Never edited, including by minimisation. */
24	  failureRecord: { attempt: number; at: string; command: string; testName: string; failedCheck?: string; exitCode?: number; failingTests?: string[]; excerpt?: string };
25	  /** Earlier forms, oldest first, kept when the obligation was minimised. */
26	  history: Array<{ at: string; attempt: number; from: { testName: string; command: string }; to: { testName: string; command: string } }>;
27	  status: "active" | "retired";
28	  replays: Array<{ attempt: number; at: string; outcome: "pass" | "fail" | "unobserved"; observedTestName?: string }>;
29	  weakenings: Array<{ at: string; path: string; kind: WeakeningKind; detail: string }>;
30	}
31	
32	export type WeakeningKind = "removed" | "skipped" | "fewer-assertions" | "unverifiable-change";
33	
34	export interface ReferenceDeclaration { requirementId: string; reference: string; authorisedAt: string }
35	
36	export type Authorisation = { ok: true; id: string } | { ok: false; reason: string };
37	
38	const now = () => new Date().toISOString();
39	
40	function requireOperator(authority: unknown): void {
41	  if (authority !== "operator") throw new Error("only the operator can authorise this");
42	}
43	
44	/** A failed, candidate-attributed attempt that named the test. */
45	function confirmedFailure(ledger: ObjectiveLedger, attempt: number, testName: string): VerificationAttempt | string {
46	  const a = ledger.verification.find((v) => v.n === attempt);
47	  if (!a) return `no attempt ${attempt} is recorded`;
48	  if (a.status !== "FAILED" || a.classification !== "CANDIDATE_FAILED") return `attempt ${attempt} is not a confirmed candidate failure`;
49	  if (!a.failingTests?.includes(testName)) return `attempt ${attempt} did not name ${JSON.stringify(testName)} as failing`;
50	  return a;
51	}
52	
53	/** Promote a confirmed failing test to an obligation. Throws unless the authority is the operator. */
54	export function authoriseObligation(ledger: ObjectiveLedger, req: { authority: "operator"; attempt: number; testName: string; at?: string }): Authorisation {
55	  requireOperator(req.authority);
56	  const found = confirmedFailure(ledger, req.attempt, req.testName);
57	  if (typeof found === "string") return { ok: false, reason: found };
58	  const list = (ledger.obligations ??= []);
59	  const existing = list.find((o) => o.status === "active" && o.testName === req.testName && o.command === found.command);
60	  if (existing) return { ok: true, id: existing.id };
61	  const at = req.at ?? now();
62	  const id = `RO${list.length + 1}`;
63	  list.push({
64	    id,
65	    testName: req.testName,
66	    command: found.command,
67	    authorisedAt: at,
68	    failureRecord: {
69	      attempt: found.n, at: found.at, command: found.command, testName: req.testName,
70	      ...(found.failedCheck ? { failedCheck: found.failedCheck } : {}),
71	      ...(found.exitCode !== undefined ? { exitCode: found.exitCode } : {}),
72	      ...(found.failingTests ? { failingTests: [...found.failingTests] } : {}),
73	      ...(found.excerpt ? { excerpt: found.excerpt } : {}),
74	    },
75	    history: [],
76	    status: "active",
77	    replays: [],
78	    weakenings: [],
79	  });
80	  return { ok: true, id };
81	}
82	
83	/** Replace the replayed form with a smaller reproduction that was itself seen failing; the failure record is untouched. */
84	export function minimiseObligation(ledger: ObjectiveLedger, id: string, to: { attempt: number; testName: string }): Authorisation {
85	  const ob = ledger.obligations?.find((o) => o.id === id && o.status === "active");
86	  if (!ob) return { ok: false, reason: `no active obligation ${id}` };
87	  const found = confirmedFailure(ledger, to.attempt, to.testName);
88	  if (typeof found === "string") return { ok: false, reason: found };
89	  ob.history.push({ at: now(), attempt: to.attempt, from: { testName: ob.testName, command: ob.command }, to: { testName: to.testName, command: found.command } });
90	  ob.testName = to.testName;
91	  ob.command = found.command;
92	  return { ok: true, id };
93	}
94	
95	export function retireObligation(ledger: ObjectiveLedger, id: string): Authorisation {
96	  const ob = ledger.obligations?.find((o) => o.id === id && o.status === "active");
97	  if (!ob) return { ok: false, reason: `no active obligation ${id}` };
98	  ob.status = "retired";
99	  return { ok: true, id };
100	}
101	
102	const active = (ledger: ObjectiveLedger) => (ledger.obligations ?? []).filter((o) => o.status === "active");
103	
104	/** The verifier commands the next candidate must be run with to replay every active obligation. */
105	export function replayCommands(ledger: ObjectiveLedger): string[] {
106	  return [...new Set(active(ledger).map((o) => o.command))];
107	}
108	
109	/** Active obligations without a pass bound to the exact test name (including never replayed or older unbound passes). */
110	export function unmetObligations(ledger: ObjectiveLedger): RegressionObligation[] {
111	  return active(ledger).filter((o) => {
112	    const last = o.replays.at(-1);
113	    // Older persisted "pass" records have no binding to the exact obligated test and must not survive this change.
114	    return last?.outcome !== "pass" || last.observedTestName !== o.testName;
115	  });
116	}
117	
118	/**
119	 * The refusal text for a completion while obligations are unmet, or undefined when none are. Names each obligation and
120	 * the command that replays it; a recorded pass of that command on the latest candidate is what discharges it.
121	 */
122	export function unmetObligationsMessage(ledger: ObjectiveLedger | undefined): string | undefined {
123	  const unmet = ledger ? unmetObligations(ledger) : [];
124	  if (!unmet.length) return undefined;
125	  const lines = unmet.map((o) => {
