100	function compactDiff(before: Buffer | undefined, after: Buffer | undefined): string[] {
101	  if (!before && !after) return [];
102	  const lines = (b: Buffer | undefined) => (b ? b.toString("utf8").split("\n") : []);
103	  const was = lines(before);
104	  const now = lines(after);
105	  const nowSet = new Set(now);
106	  const wasSet = new Set(was);
107	  const removed = was.filter((l) => !nowSet.has(l)).map((l) => `- ${l}`);
108	  const added = now.filter((l) => !wasSet.has(l)).map((l) => `+ ${l}`);
109	  const all = [...removed, ...added];
110	  return all.length > DIFF_LINES_SHOWN * 2 ? [...removed.slice(0, DIFF_LINES_SHOWN), ...added.slice(0, DIFF_LINES_SHOWN), `... (${all.length - DIFF_LINES_SHOWN * 2} more lines)`] : all;
