723	    const absolutes = [abs];
724	    let exists = false;
725	    let directory = false;
726	    try {
727	      if (fs.existsSync(abs)) {
728	        exists = true;
729	        directory = fs.statSync(abs).isDirectory();
730	        absolutes.push(fs.realpathSync(abs));
731	      } else {
732	        let ancestor = path.dirname(abs);
733	        while (!fs.existsSync(ancestor) && path.dirname(ancestor) !== ancestor) ancestor = path.dirname(ancestor);
734	        absolutes.push(path.join(fs.realpathSync(ancestor), path.relative(ancestor, abs)));
735	      }
736	    } catch {}
737	    const rels: string[] = [];
738	    for (const a of absolutes) {
739	      for (const root of roots) {
740	        const rel = path.relative(root, a).replace(/\\/g, "/");
741	        if (rel && !rel.startsWith("..") && !path.isAbsolute(rel) && !rels.includes(rel)) rels.push(rel);
742	      }
743	    }
744	    return { rels, abs, exists, directory };
745	  }
