747	  /** The first verification file under a directory (bounded walk, heavy directories skipped); "unknown" when the bound is hit, so the caller fails closed. */
748	  private classifiedFileUnder(dirAbs: string): { rel: string; found: VerificationClassification } | "unknown" | null {
749	    const roots = [this.workspace];
750	    try { roots.push(fs.realpathSync(this.workspace)); } catch {}
751	    let visited = 0;
752	    const walk = (dir: string): { rel: string; found: VerificationClassification } | "unknown" | null => {
753	      let entries: fs.Dirent[];
754	      try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return "unknown"; }
755	      for (const entry of entries) {
756	        if (++visited > 5000) return "unknown";
757	        const child = path.join(dir, entry.name);
758	        if (entry.isDirectory()) {
759	          if (HEAVY_DIRECTORIES.has(entry.name)) continue;
760	          const nested = walk(child);
761	          if (nested) return nested;
762	        } else {
763	          for (const root of roots) {
764	            const rel = path.relative(root, child).replace(/\\/g, "/");
765	            const found = rel && !rel.startsWith("..") ? this.classifyVerificationPath(rel) : null;
766	            if (found && !isConditionalConfig(rel)) return { rel, found };
767	          }
768	        }
769	      }
770	      return null;
771	    };
772	    return walk(dirAbs);
773	  }
