775	  /** Whether an edit to package.json, pyproject.toml or setup.cfg changes what tests run (the keys or sections that decide it); other edits are free. */
776	  private touchesConditionalConfig(toolName: string, args: Record<string, any>, abs: string, exists: boolean): boolean {
777	    try {
778	      const beforeText = exists ? fs.readFileSync(abs, "utf-8") : "";
779	      let afterText: string;
780	      if (toolName === "write_file") afterText = String(args.content ?? "");
781	      else if (toolName === "edit_file" && exists) {
782	        const from = String(args.old_content ?? "");
783	        const to = String(args.new_content ?? "");
784	        afterText = args.replace_all ? beforeText.split(from).join(to) : beforeText.replace(from, () => to);
785	      } else return true;
786	      if (path.basename(abs).toLowerCase() === "package.json") {
787	        const before = exists ? JSON.parse(beforeText) : {};
788	        const after = JSON.parse(afterText);
789	        return PACKAGE_VERIFICATION_KEYS.some((k) => JSON.stringify(before[k]) !== JSON.stringify(after[k]));
790	      }
791	      return JSON.stringify(verificationSections(beforeText)) !== JSON.stringify(verificationSections(afterText));
792	    } catch {
793	      return true;
794	    }
795	  }
