797	  /** Whether a tester's edit only adds to an existing test: the old text survives untouched and the addition cannot switch tests off. */
798	  private appendsToExistingTest(toolName: string, args: Record<string, any>, abs: string): boolean {
799	    try {
800	      const current = fs.readFileSync(abs, "utf-8");
801	      const appended = (from: string, to: string): boolean => {
802	        if (!to.startsWith(from)) return false;
803	        const extra = to.slice(from.length);
804	        return (from.endsWith("\n") || extra.startsWith("\n")) && !neutersTests(extra);
805	      };
806	      if (toolName === "write_file") return appended(current, String(args.content ?? ""));
807	      if (toolName === "edit_file") {
808	        const from = String(args.old_content ?? "");
809	        const to = String(args.new_content ?? "");
810	        if (!from || args.replace_all) return false;
811	        const atEnd = current === from || (current.endsWith(from) && current[current.length - from.length - 1] === "\n");
812	        return atEnd && appended(from, to);
813	      }
814	    } catch {}
815	    return false;
816	  }
