818	  /**
819	   * What an agent file edit needs: nothing (null), an operator decision, or a refusal. Only new runnable test files
820	   * are free to create; a new config, CI, verifier or policy file is gated like an edit. `ctx` is the call's own
821	   * authority; absent, the call is headless and unapproved.
822	   */
823	  public verificationEditDecision(toolName: string, args: Record<string, any>, ctx: VerificationEditContext = {}): VerificationEditDecision {
824	    if (!FILE_EDIT_TOOLS.has(toolName)) return null;
825	    const target = String(args.path || args.target_file || args.file_path || "");
826	    if (!target) return null;
827	    const configured = this.policy.verificationPaths ?? parseVerificationPolicy(undefined);
828	    const { rels, abs, exists, directory } = this.verificationCandidates(target);
829	    if (!exists && toolName !== "write_file") return null;
830	    let hit: { rel: string; found: VerificationClassification } | null = null;
831	    for (const rel of rels) {
832	      const found = this.classifyVerificationPath(rel);
833	      if (found && (!hit || found.class === "policy")) hit = { rel, found };
834	    }
835	    if (!hit && directory && toolName === "delete_file" && configured.mode !== "off" && !HEAVY_DIRECTORIES.has(path.basename(abs))) {
836	      const inside = this.classifiedFileUnder(abs);
837	      const at = rels[0] ?? target;
838	      if (inside === "unknown") {
839	        if (configured.mode !== "record") hit = { rel: at, found: { class: "verifier_script", rule: "directory too large to scan", source: "default" } };
840	      } else if (inside) hit = { rel: at, found: inside.found };
841	    }
842	    if (!hit) return null;
843	    const { rel, found } = hit;
844	    if (!exists && found.class === "test_file") return null;
845	    const mode: VerificationMode = found.class === "policy" && configured.mode !== "block" ? "approve" : configured.mode;
846	    if (mode === "off") return null;
847	    if (isConditionalConfig(rel) && !this.touchesConditionalConfig(toolName, args, abs, exists)) return null;
848	    const base = { ...found, path: rel };
849	    if (mode === "approve" && ctx.role === "tester" && found.class === "test_file" && !directory && this.appendsToExistingTest(toolName, args, abs)) {
850	      return { ...base, action: "allow", label: "role-allowed" };
851	    }
852	    if (mode === "record") return { ...base, action: "allow", label: "auto-recorded" };
853	    if (mode === "block") return { ...base, action: "deny" };
854	    if (ctx.approved?.path === rel) return { ...base, action: "allow", label: "operator-approved" };
855	    if (ctx.fullAccess && found.class !== "policy") return { ...base, action: "allow", label: "auto-recorded" };
856	    return ctx.operator ? { ...base, action: "ask" } : { ...base, action: "deny", needsDecision: true };
857	  }
