859	  /** The gate in front of a file edit: records the attempt and says whether it may run. */
860	  public authorizeVerificationEdit(toolName: string, args: Record<string, any>, ctx: VerificationEditContext = {}): { allowed: true } | { allowed: false; error: string } {
861	    const decision = this.verificationEditDecision(toolName, args, ctx);
862	    if (!decision) return { allowed: true };
863	    if (decision.action === "allow") {
864	      this.recordVerificationAttempt(decision.path, decision.class, toolName, decision.label!, ctx.role);
865	      return { allowed: true };
866	    }
867	    return this.refuseVerificationEdit(decision, toolName, ctx.role);
