876	  /**
877	   * Best-effort and record-only: a shell command that appears to write a verification-config file (sed -i, tee,
878	   * redirection, mv, cp, rm...) is noted, never blocked. SI-2 therefore does not stop a shell-capable agent from
879	   * changing how work is verified; it makes edits through the file tools a decision and the rest visible.
880	   */
881	  public recordVerificationCommand(command: string, role?: string): void {
882	    const mode = this.policy.verificationPaths?.mode ?? "approve";
883	    if (mode === "off") return;
884	    const seen = new Set<string>();
885	    const note = (token: string): void => {
886	      if (!token || token.startsWith("-")) return;
887	      const { rels, exists } = this.verificationCandidates(token);
888	      if (!exists) return;
889	      for (const rel of rels) {
890	        const found = this.classifyVerificationPath(rel);
891	        if (found && !isConditionalConfig(rel) && !seen.has(rel)) {
892	          seen.add(rel);
893	          this.recordVerificationAttempt(rel, found.class, "run_command", "auto-recorded", role);
894	        }
895	      }
896	    };
897	    for (const words of splitSubcommands(command.replace(/(>>?)(?=[^\s>])/g, "$1 ").replace(/(?<=[^\s>])(>>?)/g, " $1"))) {
898	      const redirected = words.flatMap((w, i) => (w === ">" || w === ">>") && words[i + 1] ? [words[i + 1]] : []);
899	      redirected.forEach(note);
900	      const [head, ...rest] = words;
901	      if (head === "sed" && rest.some((w) => /^-[a-zA-Z]*i/.test(w) || w.startsWith("--in-place"))) rest.forEach(note);
902	      else if (["tee", "mv", "cp", "rm", "truncate", "install", "ln"].includes(head ?? "")) rest.forEach(note);
903	    }
904	  }
