906	  /**
907	   * CS-2, opt-in (`verificationPaths.mode: "block"`): a shell command may not change the files that decide how work is
908	   * verified. Detection compares file contents before and after the command, so it does not depend on recognising the
909	   * command (`sed -i`, `python -c`, `perl -pi`, a build script...). Other modes keep the record-only behaviour of
910	   * `recordVerificationCommand` and cost nothing here.
911	   */
912	  public beginVerificationShellGuard(): VerificationShellGuard | undefined {
913	    if ((this.policy.verificationPaths?.mode ?? "approve") !== "block" && !this.shellChangeObserver) return undefined;
914	    const before = this.snapshotVerificationFiles();
915	    const refusal = (this.policy.verificationPaths?.mode ?? "approve") === "block" && !before.complete
916	      ? `${VERIFICATION_CONFIG_PROTECTED}: the bounded verification snapshot is incomplete, so shell execution is refused until the workspace can be scanned completely.`
917	      : undefined;
918	    return { before, ...(refusal ? { refusal } : {}) };
919	  }
