921	  /**
922	   * DV-3: told, after every guarded shell command, which verification files it changed (any mode, nothing reverted or
923	   * refused). The agent sets it while an operator-authorised regression obligation exists, so a test edited through the
924	   * shell is recorded from the same snapshot and diff the block mode uses.
925	   */
926	  public setShellChangeObserver(observer: ((changes: VerificationShellChange[], scan: { complete: boolean }) => void) | undefined): void {
927	    this.shellChangeObserver = observer;
928	  }
929	  private shellChangeObserver?: (changes: VerificationShellChange[], scan: { complete: boolean }) => void;
930	
931	  /** What changed in the verification files since `guard` began. In block mode each change is reverted, recorded as blocked and returned as the refusal. */
932	  public finishVerificationShellGuard(guard: VerificationShellGuard, role?: string): { error?: string; note?: string } {
933	    const after = this.snapshotVerificationFiles();
934	    const block = (this.policy.verificationPaths?.mode ?? "approve") === "block";
935	    const complete = guard.before.complete && after.complete;
936	    const changes = diffVerificationSnapshots(guard.before.files, after.files, (rel) => this.classifyVerificationPath(rel)?.class);
937	    if (changes.length || !complete) this.shellChangeObserver?.(changes, { complete });
938	    if (!block) {
939	      return {};
940	    }
941	    const note = !guard.before.complete || !after.complete
942	      ? `[nexus] Shell-write guard: the workspace is larger than the ${VERIFICATION_SNAPSHOT_MAX_ENTRIES}-entry scan limit, so verification files beyond it were not checked.`
943	      : undefined;
944	    if (!changes.length) return note ? { note } : {};
945	    const lines: string[] = [];
946	    for (const change of changes) {
947	      this.recordVerificationAttempt(change.path, change.class, "run_command", "blocked", role);
948	      const restored = this.restoreVerificationFile(change, guard.before.files.get(change.path));
949	      lines.push(`- ${change.path} (${change.class}) ${change.kind}${restored ? ", restored" : ", could not be restored"}`, ...change.diff.map((d) => `    ${d}`));
950	    }
951	    return {
952	      error: `${VERIFICATION_CONFIG_PROTECTED}: the command changed verification configuration, which the policy (verificationPaths.mode "block") does not allow a shell command to do:\n${lines.join("\n")}`,
953	      ...(note ? { note } : {}),
954	    };
955	  }
