957	  private restoreVerificationFile(change: VerificationShellChange, before: VerificationFileState | undefined): boolean {
958	    const abs = path.resolve(this.workspace, change.path);
959	    if (path.relative(this.workspace, abs).startsWith("..")) return false;
960	    try {
961	      if (change.kind === "added") {
962	        fs.rmSync(abs, { force: true });
963	        return true;
964	      }
965	      if (!before?.raw) return false;
966	      fs.mkdirSync(path.dirname(abs), { recursive: true });
967	      fs.writeFileSync(abs, before.raw);
968	      return true;
969	    } catch {
970	      return false;
971	    }
972	  }
