974	  /** The fingerprint of every verification file in the workspace (bounded walk, heavy directories skipped). Conditional configs fingerprint only the keys and sections that decide how tests run, so a dependency bump is not a change. */
975	  private snapshotVerificationFiles(): VerificationSnapshot {
976	    const files = new Map<string, VerificationFileState>();
977	    let visited = 0;
978	    let complete = true;
979	    const walk = (dir: string): void => {
980	      let entries: fs.Dirent[];
981	      try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
982	      for (const entry of entries) {
983	        if (++visited > VERIFICATION_SNAPSHOT_MAX_ENTRIES) { complete = false; return; }
984	        const child = path.join(dir, entry.name);
985	        if (entry.isDirectory()) {
986	          if (!HEAVY_DIRECTORIES.has(entry.name)) walk(child);
987	          if (!complete) return;
988	        } else if (entry.isFile()) {
989	          const rel = path.relative(this.workspace, child).replace(/\\/g, "/");
990	          if (this.classifyVerificationPath(rel)) {
991	            const state = this.fingerprintVerificationFile(child, rel);
992	            if (state) files.set(rel, state);
993	            else complete = false;
994	          }
995	        }
996	      }
997	    };
998	    walk(this.workspace);
999	    return { files, complete };
1000	  }
