1002	  private fingerprintVerificationFile(abs: string, rel: string): VerificationFileState | undefined {
1003	    try {
1004	      const stat = fs.statSync(abs);
1005	      if (stat.size > VERIFICATION_SNAPSHOT_MAX_BYTES) return undefined;
1006	      const raw = fs.readFileSync(abs);
1007	      let subject: Buffer | string = raw;
1008	      if (isConditionalConfig(rel)) {
1009	        const text = raw.toString("utf8");
1010	        try {
1011	          subject = path.basename(rel).toLowerCase() === "package.json"
1012	            ? JSON.stringify(PACKAGE_VERIFICATION_KEYS.map((k) => (JSON.parse(text) as Record<string, unknown>)[k] ?? null))
1013	            : JSON.stringify(verificationSections(text));
1014	        } catch {
1015	          subject = raw; // unparseable: any change counts
1016	        }
1017	      }
1018	      return { hash: createHash("sha256").update(subject).digest("hex"), raw: raw.length <= VERIFICATION_SNAPSHOT_KEEP_BYTES ? raw : undefined };
1019	    } catch {
1020	      return undefined;
1021	    }
1022	  }
