429	/** Enforces the invariants that make the dimensions meaningful. */
430	export function assertTurnResultInvariants(t: TurnResult): TurnResult {
431	  if (t.outcome === "VERIFIED") {
432	    if (t.execution !== "COMPLETED") throw new TurnResultInvariantError("VERIFIED requires execution COMPLETED");
433	    const v = t.verification;
434	    if (!v || v.status !== "PASSED" || !v.command || v.exitSuccess !== true) {
435	      throw new TurnResultInvariantError("VERIFIED requires passing verifier evidence");
436	    }
437	    if (t.unverifiedChangesPending) throw new TurnResultInvariantError("VERIFIED conflicts with pending unverified changes");
438	  }
439	  if (t.outcome === "REGRESSION_FREE") {
440	    if (t.execution !== "COMPLETED") throw new TurnResultInvariantError("REGRESSION_FREE requires execution COMPLETED");
441	    const v = t.verification;
442	    if (!v || v.status !== "PASSED" || !v.command || v.exitSuccess !== true) {
443	      throw new TurnResultInvariantError("REGRESSION_FREE requires passing verifier evidence");
444	    }
445	  }
446	  if (t.outcome === "NOT_REQUIRED" && (t.execution !== "COMPLETED" || t.unverifiedChangesPending)) {
447	    throw new TurnResultInvariantError("NOT_REQUIRED requires a completed turn with no pending changes");
448	  }
449	  if (t.execution === "INTERRUPTED" && !t.interruption) throw new TurnResultInvariantError("INTERRUPTED requires an interruption record");
450	  if (t.execution === "INTERRUPTED" && t.outcome !== "NOT_ESTABLISHED") {
451	    throw new TurnResultInvariantError("INTERRUPTED must not claim an engineering outcome");
452	  }
453	  if (t.execution === "BLOCKED" && t.outcome !== "NOT_ESTABLISHED") {
454	    throw new TurnResultInvariantError("BLOCKED must not claim an engineering outcome");
455	  }
456	  if (t.reason === "VERIFIER_NOT_CONVERGING" && (t.execution !== "BLOCKED" || t.outcome !== "NOT_ESTABLISHED" || !t.convergence)) {
457	    throw new TurnResultInvariantError("VERIFIER_NOT_CONVERGING requires a BLOCKED, NOT_ESTABLISHED turn carrying its attempt history");
458	  }
459	  if (t.reason === "TOOL_CALL_LOOP" && (t.execution !== "BLOCKED" || t.outcome !== "NOT_ESTABLISHED" || !t.repeatedCall)) {
460	    throw new TurnResultInvariantError("TOOL_CALL_LOOP requires a BLOCKED, NOT_ESTABLISHED turn carrying the repeated call");
461	  }
462	  if ((t.reason === "NEEDS_INPUT" || t.needsInput) && (t.reason !== "NEEDS_INPUT" || t.execution !== "BLOCKED" || t.outcome !== "NOT_ESTABLISHED" || !t.needsInput)) {
463	    throw new TurnResultInvariantError("NEEDS_INPUT requires a BLOCKED, NOT_ESTABLISHED turn carrying the question (and only that reason carries one)");
464	  }
465	  if (t.furtherNeedsInput && !t.needsInput) {
466	    throw new TurnResultInvariantError("furtherNeedsInput is only carried with the first question");
467	  }
468	  if (t.execution === "FAILED" && t.outcome !== "NOT_ESTABLISHED") {
469	    throw new TurnResultInvariantError("FAILED must not claim an engineering outcome");
470	  }
471	  if (t.acceptance !== "NOT_REQUESTED" && t.acceptance !== "ACCEPTED" && t.acceptance !== "NOT_ACCEPTED") {
472	    throw new TurnResultInvariantError("unknown acceptance value");
473	  }
474	  return t;
475	}
