515	/**
516	 * What this turn did when it differs from what an UNVERIFIED outcome suggests (D-04); the TUI words the same facts
517	 * (live_state.rs unverified_cause; the same facts and conditions, shorter phrasing). Only VERIFICATION_NOT_RUN is about verifier runs, so only it gets this text.
518	 */
519	function evidenceTail(t: TurnResult): string {
520	  const e = t.turnEvidence;
521	  if (!e || t.reason !== "VERIFICATION_NOT_RUN") return "";
522	  if (e.workspaceChanged === "no" && e.carriedChanges) {
523	    return `; no files changed this turn${e.denied ? ` (${e.denied} action${e.denied === 1 ? "" : "s"} denied)` : ""}, changes from an earlier turn are still unverified`;
524	  }
525	  const changed = e.workspaceChanged === "unknown" ? "; files may have changed" : "";
526	  const last = e.verifierRuns.at(-1);
527	  if (last?.phase === "before_change") return `${changed}; ${shortCommand(last.command)} ran before the change; nothing checked the change itself`;
528	  if (last?.phase === "completion") return `${changed}; ${shortCommand(last.command)} ran, but the change was edited after it`;
529	  return changed;
530	}
