    finalOutputComplete: false,
    verification: null,
    interruption: null,
    inferenceFailure: null,
    steps: { used: stepsUsed, max: maxSteps, limitReached: false },
    unverifiedChangesPending,
    finishedAt: new Date().toISOString(),
  }));

