532	export function summarizeTurn(t: TurnResult): { heading: string; line: string } {
533	  const exec = t.execution;
534	  const tail = t.reason ? ` (${t.reason}${t.detail ? `: ${t.detail}` : ""})` : "";
535	  if (exec === "INTERRUPTED") {
536	    const i = t.interruption;
537	    const extra = i?.outstandingTool ? ` - ${i.outstandingTool} ${i.outstandingToolSettled ? "settled" : "still settling"}` : "";
538	    return { heading: "TURN INTERRUPTED", line: `execution=INTERRUPTED outcome=NOT_ESTABLISHED${extra}; ${i?.undispatchedToolCalls ?? 0} tool call(s) not dispatched` };
539	  }
540	  if (exec === "FAILED") return { heading: "TURN FAILED", line: `execution=FAILED outcome=NOT_ESTABLISHED${tail}` };
541	  if (exec === "BLOCKED" && t.capacity) {
542	    const c = t.capacity;
543	    const fate = c.pendingMessageRetained ? "your message and the conversation so far are kept" : "your message was not added to the conversation";
544	    if (c.missingRequirements?.length) {
545	      return {
546	        heading: "TURN BLOCKED - OBJECTIVE REQUIREMENT NOT RETAINED",
547	        line: `execution=BLOCKED outcome=NOT_ESTABLISHED (CONTEXT_CAPACITY_EXCEEDED: the request would not carry requirement(s) ${c.missingRequirements.join(", ")}). No request was sent; ${fate}. Requirements are never cut to fit: raise --context-limit or narrow the objective.`,
548	      };
549	    }
550	    if (c.unmeasured) {
551	      return {
552	        heading: "TURN BLOCKED - REQUEST NOT MEASURED",
553	        line: `execution=BLOCKED outcome=NOT_ESTABLISHED (CONTEXT_CAPACITY_EXCEEDED: ${c.unmeasured}). No request was sent. Strict token counting is on (--strict-token-count / NEXUS_STRICT_TOKEN_COUNT=1); turn it off to proceed on the labelled estimate.`,
554	      };
555	    }
556	    return {
557	      heading: "TURN BLOCKED - CONTEXT FULL",
558	      line: `execution=BLOCKED outcome=NOT_ESTABLISHED (CONTEXT_CAPACITY_EXCEEDED: ${c.estimatedPromptTokens} prompt${c.promptCountSource ? ` (${c.promptCountSource})` : ""} + ${c.completionReserveTokens} completion + ${c.toolResponseReserveTokens} tool reserve > ${c.contextLimit} limit). ` +
559	        `${c.modelCalled ? "No further request was sent" : "No request was sent"}; ${fate}. ` +
560	        `Raise --context-limit, run /clear, or ask for something narrower; /compact may not help if one retained result is itself too large.`,
561	    };
562	  }
563	  if (exec === "BLOCKED" && t.reason === "VERIFIER_NOT_CONVERGING") {
564	    return {
565	      heading: "TURN BLOCKED - VERIFIER NOT CONVERGING",
566	      line: `execution=BLOCKED outcome=NOT_ESTABLISHED (VERIFIER_NOT_CONVERGING: ${t.convergence?.evidence ?? t.detail ?? "repeated verifier failures"}). Nothing is verified; the operator decides how to proceed.`,
567	    };
568	  }
569	  if (exec === "BLOCKED" && t.reason === "NEEDS_INPUT" && t.needsInput) {
570	    return {
571	      heading: "TURN BLOCKED - NEEDS INPUT",
572	      line: `execution=BLOCKED outcome=NOT_ESTABLISHED (NEEDS_INPUT ${t.needsInput.id}: ${t.needsInput.prompt}). ${t.needsInput.kind === "steering_conflict" ? "Send the steering again to decide it at the prompt, or answer" : "Resume"} with --answer ${t.needsInput.options.some((o) => o.id === "reply") ? `${t.needsInput.id}=reply:<what to do>` : `${t.needsInput.id}=approve or ${t.needsInput.id}=decline`}.${t.furtherNeedsInput?.length ? ` ${t.furtherNeedsInput.length} more question(s) wait behind it: ${t.furtherNeedsInput.map((q) => q.id).join(", ")}.` : ""}`,
573	    };
574	  }
575	  if (exec === "BLOCKED" && t.reason === "TOOL_CALL_LOOP") {
576	    return {
577	      heading: "TURN BLOCKED - REPEATED TOOL CALL",
578	      line: `execution=BLOCKED outcome=NOT_ESTABLISHED (TOOL_CALL_LOOP: ${t.detail ?? "the same tool call repeated"}). Nothing is verified; the operator decides how to proceed.`,
579	    };
580	  }
581	  if (exec === "BLOCKED") return { heading: "TURN BLOCKED", line: `execution=BLOCKED outcome=NOT_ESTABLISHED${tail}` };
582	  if (exec === "LIMIT_REACHED") {
583	    const c = t.continuation;
584	    const segments = c && c.segments > 1 ? ` across ${c.segments} segments of ${c.segmentSteps}` : "";
585	    if (t.reason === "STEP_PAUSED") {
586	      return { heading: "STEP PAUSED", line: `execution=LIMIT_REACHED outcome=NOT_ESTABLISHED (STEP_PAUSED: ${t.detail ?? "paused after one model/tool cycle"})` };
587	    }
588	    if (t.reason === "STAGNATION_DETECTED") {
589	      return { heading: "STOPPED - NO PROGRESS", line: `execution=LIMIT_REACHED outcome=NOT_ESTABLISHED (STAGNATION_DETECTED${t.detail ? `: ${t.detail}` : ""}; ${t.steps.used} steps${segments})` };
590	    }
591	    if (t.reason === "TIME_BUDGET_EXHAUSTED") {
592	      return { heading: "TIME BUDGET EXHAUSTED", line: `execution=LIMIT_REACHED outcome=NOT_ESTABLISHED (TIME_BUDGET_EXHAUSTED${t.detail ? `: ${t.detail}` : ""}; ${t.steps.used} steps${segments})` };
593	    }
594	    if (t.reason === "STEP_BUDGET_EXHAUSTED") {
595	      return { heading: "STEP BUDGET EXHAUSTED", line: `execution=LIMIT_REACHED outcome=NOT_ESTABLISHED (${t.steps.used}/${t.steps.max} steps${segments}; raise --max-total-steps to allow more)` };
596	    }
597	    if (t.reason === "TOOL_INVOCATION_BUDGET_EXHAUSTED") {
598	      return { heading: "TOOL INVOCATION BUDGET EXHAUSTED", line: `execution=LIMIT_REACHED outcome=NOT_ESTABLISHED (${t.detail ?? "objective tool invocation limit reached"}; raise --max-tool-invocations only when starting a new objective)` };
599	    }
600	    return { heading: "STEP LIMIT REACHED", line: `execution=LIMIT_REACHED outcome=NOT_ESTABLISHED (${t.steps.used}/${t.steps.max} steps)` };
601	  }
602	  switch (t.outcome) {
603	    case "VERIFIED":
604	      return { heading: "TASK COMPLETED - VERIFIED", line: `execution=COMPLETED outcome=VERIFIED (${t.verification?.command})${contextTail(t)}` };
605	    case "REGRESSION_FREE":
606	      return { heading: "TASK COMPLETED - REGRESSION FREE", line: `execution=COMPLETED outcome=REGRESSION_FREE (${t.verification?.command})${tail}${contextTail(t)}` };
607	    case "NOT_REQUIRED":
608	      return { heading: "TURN ENDED - NO CHANGES TO VERIFY", line: `execution=COMPLETED outcome=NOT_REQUIRED modelStop=${t.modelStop}` };
609	    case "UNVERIFIED":
610	      return { heading: "TURN ENDED - UNVERIFIED", line: `execution=COMPLETED outcome=UNVERIFIED${tail}${evidenceTail(t)}` };
611	    default:
612	      if (t.reason === "REQUIREMENTS_INCOMPLETE") {
613	        return { heading: "TURN ENDED - REQUIREMENTS OPEN", line: `execution=COMPLETED outcome=NOT_ESTABLISHED${tail}` };
614	      }
615	      return { heading: "TURN ENDED - NOT ESTABLISHED", line: `execution=COMPLETED outcome=NOT_ESTABLISHED${tail}` };
616	  }
617	}
