1733	/**
1734	 * Whether a passing verifier run is evidence about the changed files (VERIFIED) rather than only a regression check
1735	 * (REGRESSION_FREE). It must show executed tests import every changed product file
1736	 * explicitly declared by the operator before the turn. Candidate-controlled test
1737	 * output, changed tests, inline tests, and runtime-graph membership alone cannot
1738	 * establish deliverable scope.
1739	 * Verification-only work still requires an operator-declared scope and pre-turn test snapshot; an empty change list is
1740	 * not itself a deliverable declaration.
1741	 */
1742	export function isVerifierDeliverableBound(
1743	  workspace: string,
1744	  changedFiles: string[],
1745	  verifierCommand: string,
1746	  testOutput: string = "",
1747	  trustedDeliverables?: ReadonlySet<string>,
1748	  baselineTests?: ReadonlyMap<string, string>,
1749	): boolean {
1750	  if (!hasExecutedTests(testOutput)) return false;
1751	  const root = path.resolve(workspace);
1752	  const rel = (file: string) => path.relative(root, path.resolve(root, file)).replace(/\\/g, "/");
1753	
1754	  // An empty change list is not an operator scope. This matters for verification-only
1755	  // work units: a generic passing suite is regression evidence, not proof of a declared
1756	  // product deliverable. The operator-declared scope and pre-turn test snapshot are both
1757	  // required even when the current turn made no edits.
1758	  if (!baselineTests?.size || !trustedDeliverables?.size) return false;
1759	  const declaredScope = [...trustedDeliverables].map((file) => rel(file));
1760	  if (declaredScope.some((file) => !file || file.startsWith("../") || path.isAbsolute(file) || !isSafeWorkspaceFile(root, file))) return false;
1761	  const declaredScopeSet = new Set(declaredScope);
1762	  const changedNonTestFiles = changedFiles.filter((file) => !TEST_PATH.test(rel(file)));
1763	  // A runtime graph cannot distinguish product code from dual-use oracle code.
1764	  // Require a pre-turn operator declaration and reject any changed product path
1765	  // outside that immutable task scope.
1766	  const changedTargets = changedNonTestFiles.map((file) => rel(file));
1767	  if (changedTargets.some((file) => !declaredScopeSet.has(file) || !isSafeWorkspaceFile(root, file))) return false;
1768	  const tokens = extractPathTokens(root, `${verifierCommand}\n${testOutput}`);
1769	  const isFiltered = isFilteredVerifierCommand(verifierCommand);
1770	  const baselineHasPytestPlugins = [...baselineTests].some(([testFile, content]) =>
1771	    testFile.endsWith(".py") && /\bpytest_plugins\b/.test(stripPythonStringsAndComments(content)),
1772	  );
1773	
1774	  const testFileExecuted = (testFileRel: string) => {
1775	    // An unfiltered verifier run that executed tests ran the repository test suite
1776	    if (!isFiltered) {
1777	      if (testFileRel.endsWith(".py")) {
1778	        return isPythonTestExecutionCandidate(root, testFileRel, verifierCommand, baselineHasPytestPlugins);
1779	      }
1780	      return true;
1781	    }
1782	    return tokens.has(testFileRel) || verifierCommand.includes(testFileRel);
1783	  };
1784	
1785	  // Verifier output is candidate-influenced. Bind every operator-declared product
1786	  // file to an actually executed, pre-existing test import instead of path text.
1787	  return declaredScope.every((file) => [...baselineTests].some(([testRel, content]) =>
1788	    testFileExecuted(testRel) &&
1789	    Boolean(content) && testReferencesFile(content, testRel, rel(file), root),
1790	  ));
1791	}
