1793	/** Resolve package-declared runtime entry points to the files that actually implement them. */
1794	export function workspaceRuntimeFiles(root: string): Set<string> {
1795	  const workspace = path.resolve(root);
1796	  const manifests: string[] = [];
1797	  const walk = (directory: string, depth: number) => {
1798	    if (depth > 5 || manifests.length >= 128) return;
1799	    let entries: fs.Dirent[];
1800	    try { entries = fs.readdirSync(directory, { withFileTypes: true }); } catch { return; }
1801	    for (const entry of entries) {
1802	      if (entry.name === "node_modules" || entry.name === ".git" || entry.name === "dist" || entry.name === "build") continue;
1803	      const full = path.join(directory, entry.name);
1804	      if (entry.isDirectory()) walk(full, depth + 1);
1805	      else if (entry.name === "package.json") manifests.push(full);
1806	    }
1807	  };
1808	  walk(workspace, 0);
1809	
1810	  const product = new Set<string>();
1811	  const sourceExtensions = [".js", ".cjs", ".mjs", ".ts", ".tsx", ".jsx"];
1812	  const resolveModule = (base: string): string | null => {
1813	    const sourceAliases = /\.(?:c|m)?js$/.test(base)
1814	      ? [base.replace(/\.(?:c|m)?js$/, ".ts"), base.replace(/\.(?:c|m)?js$/, ".tsx")]
1815	      : [];
1816	    const candidates = [base, ...sourceAliases, ...sourceExtensions.map((extension) => base + extension), ...sourceExtensions.map((extension) => path.join(base, `index${extension}`))];
1817	    for (const candidate of candidates) {
1818	      if (!candidate.startsWith(workspace + path.sep)) continue;
1819	      try {
1820	        const stat = fs.lstatSync(candidate);
1821	        const real = fs.realpathSync(candidate);
1822	        if (!stat.isSymbolicLink() && real.startsWith(workspace + path.sep) && stat.isFile()) return candidate;
1823	      } catch {}
1824	    }
1825	    return null;
1826	  };
1827	  const mapBuiltEntryToSource = (packageRoot: string, entry: string): string[] => {
1828	    const candidates = [entry];
1829	    for (const tsconfigName of ["tsconfig.json", "tsconfig.build.json"]) {
1830	      try {
1831	        const config = JSON.parse(fs.readFileSync(path.join(packageRoot, tsconfigName), "utf8"));
1832	        const options = config.compilerOptions ?? {};
1833	        const outDir = options.outDir;
1834	        const rootDir = options.rootDir;
1835	        if (typeof outDir !== "string" || typeof rootDir !== "string") continue;
1836	        const out = path.resolve(packageRoot, outDir);
1837	        const resolvedEntry = path.resolve(packageRoot, entry);
1838	        if (resolvedEntry !== out && !resolvedEntry.startsWith(out + path.sep)) continue;
1839	        const relative = path.relative(out, resolvedEntry).replace(/\\/g, "/").replace(/\.(?:c|m)?js$/, "");
1840	        candidates.unshift(path.join(rootDir, relative + ".ts"), path.join(rootDir, relative + ".tsx"), path.join(rootDir, relative + ".js"));
1841	      } catch {}
1842	    }
1843	    return candidates;
1844	  };
1845	  const collectEntries = (value: unknown, entries: Set<string>) => {
1846	    if (typeof value === "string" && value.startsWith(".")) entries.add(value);
1847	    else if (Array.isArray(value)) value.forEach((item) => collectEntries(item, entries));
1848	    else if (value && typeof value === "object") Object.values(value).forEach((item) => collectEntries(item, entries));
1849	  };
1850	  const pending: string[] = [];
1851	  for (const manifest of manifests) {
1852	    let pkg: any;
1853	    try { pkg = JSON.parse(fs.readFileSync(manifest, "utf8")); } catch { continue; }
1854	    const packageRoot = path.dirname(manifest);
1855	    const entries = new Set<string>();
1856	    for (const key of ["main", "module", "source", "browser", "exports", "bin"]) collectEntries(pkg[key], entries);
1857	    for (const key of ["start", "serve", "dev"]) {
1858	      const script = pkg.scripts?.[key];
1859	      if (typeof script === "string") {
1860	        for (const match of script.matchAll(/(?:node|tsx|ts-node)\s+([^\s;&|]+)/g)) entries.add(match[1]);
1861	      }
1862	    }
1863	    for (const entry of entries) {
1864	      if (!entry.startsWith(".")) continue;
1865	      for (const candidate of mapBuiltEntryToSource(packageRoot, entry)) {
1866	        const resolved = resolveModule(path.resolve(packageRoot, candidate));
1867	        if (resolved) pending.push(resolved);
1868	      }
1869	    }
1870	  }
1871	
1872	  const visited = new Set<string>();
1873	  const importPattern = /(?:\bfrom\s*|\bimport\s*\(|\brequire\s*\()\s*["']([^"']+)["']|(?:^|[;\n])\s*import\s*["']([^"']+)["']/gm;
1874	  while (pending.length && visited.size < 4096) {
1875	    const file = pending.pop()!;
1876	    if (visited.has(file)) continue;
1877	    visited.add(file);
1878	    product.add(path.relative(workspace, file).replace(/\\/g, "/"));
1879	    let text: string;
1880	    try { text = fs.readFileSync(file, "utf8"); } catch { continue; }
1881	    for (const match of text.matchAll(importPattern)) {
1882	      const specifier = match[1] ?? match[2];
1883	      if (!specifier.startsWith(".")) continue;
1884	      const dependency = resolveModule(path.resolve(path.dirname(file), specifier));
1885	      if (dependency) pending.push(dependency);
1886	    }
1887	  }
1888	  return product;
1889	}
