1891	/**
1892	 * A test import binds a changed file only when a pre-existing package runtime
1893	 * entry point reaches that file. Directory names such as `src/` are not
1894	 * authority: unreferenced assertion helpers under a source-looking directory
1895	 * remain test support, while an explicitly exported root module is a product.
1896	 */
1897	export function isWorkspaceTestSupportFile(root: string, file: string): boolean {
1898	  const workspace = path.resolve(root);
1899	  const absolute = path.resolve(workspace, file);
1900	  const relative = path.relative(workspace, absolute).replace(/\\/g, "/");
1901	  if (!relative || relative === ".." || relative.startsWith("../")) return true;
1902	  return !workspaceRuntimeFiles(workspace).has(relative);
1903	}

