554	          }
555	        }
556	      } catch {
557	        // Fallback to default
558	      }
559	    }
560	
561	    if (!isJson && (config.provider || config.plannerProvider || config.coderProvider)) console.error(pc.dim(describeTarget(config)));
562	    const app = new ApplicationCore(config);
563	
564	    if (options.forkSession !== undefined) {
565	      try {
566	        // `run --resume` reads the task store, so the fork is made there (the source is a task id, as for --resume).
567	        const forked = startFork(new SessionManager(app.getStateManager().getBaseDir(), () => app.getAgent().getWorkspacePathIdentity()), options);
568	        console.error(forkStartNotice(forked));
569	        options.resume = forked.id;
570	      } catch (err: any) {
571	        console.error(`error: ${redactDiagnosticForOutput(String(err?.message ?? err))}`);
572	        app.shutdown();
573	        exitAfterFlush(runExitCode("resume_unavailable"));
574	        return;
575	      }
576	    }
577	
578	    let resumeTaskId: string | undefined;
579	    if ((options.resume === undefined || options.resume === false) && !prompt) {
580	      console.error("error: missing required argument 'prompt'");
581	      app.shutdown();
582	      exitAfterFlush(runExitCode("missing_prompt"));
583	      return;
584	    }
585	
586	    // Operator stop authority: first SIGINT cancels the active turn; a second one terminates immediately.
587	    const abort = new AbortController();
588	    let sigints = 0;
