632	
633	      const cloud = UsageLedger.global().cloudTotals();
634	      if (emitEvent) {
635	        emitEvent("result", { ...runJsonResult(result, cloud) });
636	      } else if (isJson) {
637	        console.log(JSON.stringify(runJsonResult(result, cloud), null, 2));
638	      } else if (cloud.requests) {
639	        console.error(pc.dim(UsageLedger.global().summary()!));
640	      }
641	
642	      app.shutdown();
643	      exitAfterFlush(result.exitCode);
644	    } catch (err: any) {
645	      if (emitEvent) {
646	        emitEvent("error", { taskId: app.getTaskId(), message: redactDiagnosticForOutput(String(err?.message ?? err)) });
647	      } else if (isJson) {
648	        console.log(JSON.stringify({
649	          schema_version: RUN_RESULT_SCHEMA_VERSION,
650	          taskId: app.getTaskId(),
651	          success: false,
652	          status: "failed",
653	          prompt: redactDiagnosticForOutput(prompt),
654	          output: "",
655	          plan: [],
656	          milestones: [],
657	          validationReceipts: [],
658	          tokenStats: { prompt: 0, completion: 0, total: 0 },
659	          durationMs: 0,
